import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { useApp } from '../context';
import { Button, Badge, Card, Input, Avatar, Spinner } from '../components/UI';
import { Product } from '../types';

export const StorePage: React.FC = () => {
    const { vendorId } = useParams<{ vendorId: string }>();
    const navigate = useNavigate();
    const { vendors, products, addToCart, cart, removeFromCart, toggleFavorite, favorites, showToast } = useApp();

    const vendor = vendors.find(v => v.vendorId === vendorId);
    const vendorProducts = products.filter(p => p.vendorId === vendorId && p.status === 'approved');

    if (!vendor) return <div className="p-8 text-center text-gray-500 dark:text-gray-400">Store not found</div>;

    const whatsappUrl = vendor.contactPhone 
        ? `https://wa.me/${vendor.contactPhone.replace(/[^0-9]/g, '').replace(/^0/, '233')}?text=Hi ${vendor.storeName}, I saw your store on LYNQED!`
        : null;

    const handleShare = async () => {
        const shareUrl = window.location.href;
        const shareData = {
            title: `Check out ${vendor.storeName} on LYNQED!`,
            text: `Find amazing products at ${vendor.storeName} on campus.`,
            url: shareUrl
        };

        try {
            // Use canShare if available to prevent "Invalid URL" or other sharing errors
            if (navigator.share && (typeof navigator.canShare !== 'function' || navigator.canShare(shareData))) {
                await navigator.share(shareData);
            } else {
                throw new Error("Sharing not supported or invalid data");
            }
        } catch (err) {
            console.error("Error sharing:", err);
            // Fallback to clipboard
            try {
                await navigator.clipboard.writeText(shareUrl);
                showToast("Store link copied to clipboard!", "success");
            } catch (clipboardErr) {
                console.error("Clipboard fallback failed:", clipboardErr);
            }
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-20 animate-fade-in">
            {/* Store Header */}
            <div className="bg-white dark:bg-darkSurface p-6 md:p-10 shadow-sm border-b border-gray-100 dark:border-gray-800">
                <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center md:items-start gap-6">
                     <Avatar src={vendor.storeAvatarUrl} name={vendor.storeName} size="xl" className="md:w-32 md:h-32 rounded-3xl" />
                     <div className="flex-1 text-center md:text-left">
                         <div className="flex items-center justify-center md:justify-start gap-2">
                            <h1 className="text-2xl md:text-3xl font-display font-black text-gray-900 dark:text-white tracking-tight">{vendor.storeName}</h1>
                            {vendor.isApproved && <i className="fa-solid fa-circle-check text-blue-500 text-lg"></i>}
                         </div>
                         <div className="flex items-center justify-center md:justify-start gap-1 text-sm text-gray-500 dark:text-gray-400 mt-2 mb-3">
                             <i className="fa-solid fa-location-dot text-red-500"></i> {vendor.location}
                             <span className="mx-2 opacity-30">•</span>
                             <i className="fa-solid fa-star text-yellow-400"></i> {vendor.rating}
                         </div>
                         <p className="text-gray-600 dark:text-gray-400 max-w-2xl leading-relaxed">{vendor.storeDescription}</p>

                         {/* Actions Wrapper */}
                         <div className="flex flex-wrap items-center justify-center md:justify-start gap-3 mt-6">
                            {whatsappUrl && (
                                <a 
                                    href={whatsappUrl}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="flex items-center justify-center gap-2 bg-[#25D366] text-white px-6 py-3 rounded-2xl text-sm font-bold hover:bg-[#128C7E] transition-all shadow-lg shadow-green-500/20 active:scale-95"
                                >
                                    <i className="fa-brands fa-whatsapp text-lg"></i> Chat on WhatsApp
                                </a>
                            )}
                            <button 
                                onClick={handleShare}
                                className="flex items-center justify-center gap-2 bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 px-6 py-3 rounded-2xl text-sm font-bold hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors border border-gray-200 dark:border-gray-700 active:scale-95"
                            >
                                <i className="fa-solid fa-share-nodes"></i> Share Store
                            </button>
                         </div>
                     </div>
                </div>
            </div>

            {/* Product Grid Section */}
            <div className="max-w-7xl mx-auto p-4 md:p-8">
                <div className="flex items-center gap-3 mb-6">
                    <h2 className="font-display font-black text-gray-900 dark:text-white text-lg uppercase tracking-wider">Catalog</h2>
                    <div className="h-px flex-1 bg-gray-200 dark:bg-gray-800"></div>
                    <Badge color="blue">{vendorProducts.length} Items</Badge>
                </div>

                {vendorProducts.length === 0 ? (
                    <div className="text-center py-24 bg-white dark:bg-darkSurface rounded-[2.5rem] border border-dashed border-gray-200 dark:border-gray-800">
                        <i className="fa-solid fa-box-open text-4xl mb-4 text-gray-200"></i>
                        <p className="text-gray-400 font-medium">No active listings from this vendor yet.</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4 md:gap-6">
                        {vendorProducts.map(product => {
                            const isFav = favorites.includes(product.id);
                            const isInCart = cart.some(item => item.productId === product.id);

                            return (
                                <div 
                                    key={product.id} 
                                    className="bg-white dark:bg-darkSurface rounded-[2rem] overflow-hidden shadow-card hover:shadow-xl transition-all duration-500 group relative flex flex-col h-full cursor-pointer border border-gray-50 dark:border-gray-800/50"
                                    onClick={() => navigate(`/buyer/product/${product.id}`)}
                                >
                                    <div className="aspect-[4/5] w-full relative overflow-hidden bg-gray-50 dark:bg-gray-900">
                                        <img 
                                            src={product.images[0]} 
                                            alt={product.title} 
                                            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" 
                                        />
                                        <button 
                                            className="absolute top-3 right-3 z-10 w-9 h-9 rounded-full bg-white/90 dark:bg-darkBg/90 backdrop-blur-md border border-gray-100 dark:border-gray-800 text-gray-400 hover:text-red-500 flex items-center justify-center transition-all shadow-sm active:scale-90"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                toggleFavorite(product.id);
                                            }}
                                        >
                                            <i className={`${isFav ? 'fa-solid text-red-500' : 'fa-regular'} fa-heart text-sm`}></i>
                                        </button>
                                        {product.stock === 0 && (
                                            <div className="absolute inset-0 bg-black/50 backdrop-blur-[2px] flex items-center justify-center z-10">
                                                <span className="bg-black/80 text-white text-[10px] px-3 py-1.5 rounded-full font-black uppercase tracking-widest border border-white/20">Sold Out</span>
                                            </div>
                                        )}
                                    </div>
                                    <div className="p-4 flex flex-col justify-between flex-grow">
                                        <div className="mb-2">
                                            <h3 className="text-sm text-gray-800 dark:text-white font-bold leading-snug line-clamp-2 group-hover:text-primary transition-colors">{product.title}</h3>
                                        </div>
                                        <div className="flex items-center justify-between pt-2">
                                            <span className="text-base font-black text-gray-900 dark:text-white">₵{product.price.toFixed(2)}</span>
                                            <button 
                                                className={`w-9 h-9 rounded-full flex items-center justify-center text-white transition-all shadow-md active:scale-90 ${product.stock === 0 ? 'bg-gray-200 dark:bg-gray-800 cursor-not-allowed text-gray-400' : isInCart ? 'bg-green-500' : 'bg-gray-900 dark:bg-white dark:text-black hover:bg-primary hover:text-white'}`}
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (product.stock > 0) {
                                                        isInCart ? removeFromCart(product.id) : addToCart(product);
                                                    }
                                                }}
                                                disabled={product.stock === 0}
                                            >
                                                <i className={`fa-solid ${isInCart ? 'fa-check' : 'fa-plus'} text-xs`}></i>
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
};

export const ProductDetail: React.FC = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { products, addToCart, cart, removeFromCart, updateCartQuantity, vendors, favorites, toggleFavorite, showToast } = useApp();
    const [selectedImageIndex, setSelectedImageIndex] = useState(0);
    const scrollContainerRef = useRef<HTMLDivElement>(null);

    const product = products.find(p => p.id === id);
    const vendor = vendors.find(v => v.vendorId === product?.vendorId);

    // Recommendations
    const relatedProducts = products
        .filter(p => p.category === product?.category && p.id !== product?.id && p.status === 'approved')
        .slice(0, 10);

    const [quantity, setQuantity] = useState(1);

    if (!product) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const cartItem = cart.find(i => i.productId === product.id);
    const isInCart = !!cartItem;
    const isFav = favorites.includes(product.id);

    useEffect(() => {
        if (cartItem) setQuantity(cartItem.quantity);
    }, [cartItem]);

    const handleQuantity = (delta: number) => {
        const newQ = Math.max(1, Math.min(product.stock, quantity + delta));
        setQuantity(newQ);
        if (isInCart) updateCartQuantity(product.id, newQ);
    };

    const handleBuyNow = () => {
        if (isInCart) {
            updateCartQuantity(product.id, quantity);
        } else {
            addToCart(product, quantity);
        }
        navigate('/buyer/checkout');
    };

    const handleShare = async () => {
        const shareUrl = window.location.href;
        const shareData = {
            title: product.title,
            text: `Check out this ${product.title} from ${vendor?.storeName || 'LYNQED'}!`,
            url: shareUrl
        };

        try {
            if (navigator.share && (typeof navigator.canShare !== 'function' || navigator.canShare(shareData))) {
                await navigator.share(shareData);
            } else {
                throw new Error("Sharing not supported or invalid data");
            }
        } catch (err) {
            console.error("Error sharing:", err);
            // Fallback to clipboard
            try {
                await navigator.clipboard.writeText(shareUrl);
                showToast("Product link copied to clipboard!", "success");
            } catch (clipboardErr) {
                console.error("Clipboard fallback failed:", clipboardErr);
            }
        }
    };

    const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
        const container = e.currentTarget;
        const index = Math.round(container.scrollLeft / container.clientWidth);
        if (index !== selectedImageIndex) {
            setSelectedImageIndex(index);
        }
    };

    const scrollToImage = (index: number) => {
        if (scrollContainerRef.current) {
            scrollContainerRef.current.scrollTo({
                left: index * scrollContainerRef.current.clientWidth,
                behavior: 'smooth'
            });
            setSelectedImageIndex(index);
        }
    };

    const whatsappUrl = vendor?.contactPhone 
        ? `https://wa.me/${vendor.contactPhone.replace(/[^0-9]/g, '').replace(/^0/, '233')}?text=Hi ${vendor.storeName}, I saw your product "${product.title}" on LYNQED and I'm interested!`
        : null;

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-20 animate-fade-in">
            {/* Breadcrumbs & Header */}
            <div className="bg-white/80 dark:bg-darkSurface/80 backdrop-blur-md border-b border-gray-200 dark:border-gray-800 sticky top-0 z-30 px-4 py-3 flex items-center gap-3">
                <button onClick={() => navigate(-1)} className="w-9 h-9 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-600 dark:text-gray-300">
                    <i className="fa-solid fa-arrow-left"></i>
                </button>
                <div className="text-xs text-gray-500 dark:text-gray-400 flex items-center gap-2 overflow-hidden whitespace-nowrap">
                    <Link to="/buyer/dashboard" className="hover:text-primary transition-colors">Home</Link>
                    <i className="fa-solid fa-chevron-right text-[8px] opacity-40"></i>
                    <span className="truncate">{product.category}</span>
                    <i className="fa-solid fa-chevron-right text-[8px] opacity-40"></i>
                    <span className="text-gray-900 dark:text-white font-bold truncate max-w-[120px] md:max-w-xs">{product.title}</span>
                </div>
                <div className="ml-auto flex gap-2">
                    <button onClick={() => toggleFavorite(product.id)} className={`w-9 h-9 rounded-full flex items-center justify-center transition-all ${isFav ? 'bg-red-50 text-red-500' : 'text-gray-400 hover:text-red-500'}`}>
                        <i className={`${isFav ? 'fa-solid' : 'fa-regular'} fa-heart`}></i>
                    </button>
                    <button onClick={handleShare} className="w-9 h-9 rounded-full flex items-center justify-center text-gray-400 hover:text-primary transition-all">
                        <i className="fa-solid fa-share-nodes"></i>
                    </button>
                </div>
            </div>

            <div className="max-w-7xl mx-auto p-4 md:p-8">
                <div className="bg-white dark:bg-darkSurface rounded-[2.5rem] shadow-soft overflow-hidden grid grid-cols-1 lg:grid-cols-2 gap-0">

                    {/* Left: Swippable Image Gallery */}
                    <div className="p-4 md:p-10 flex flex-col gap-6">
                        <div className="aspect-square w-full bg-gray-50 dark:bg-gray-900 rounded-[2rem] overflow-hidden border border-gray-100 dark:border-gray-800 relative">
                            <div 
                                ref={scrollContainerRef}
                                onScroll={handleScroll}
                                className="w-full h-full flex overflow-x-auto snap-x snap-mandatory hide-scrollbar"
                            >
                                {product.images.map((img, idx) => (
                                    <div key={idx} className="w-full h-full flex-shrink-0 snap-center flex items-center justify-center p-6">
                                        <img 
                                            src={img} 
                                            alt={`${product.title} ${idx + 1}`} 
                                            className="max-w-full max-h-full object-contain" 
                                        />
                                    </div>
                                ))}
                            </div>

                            {product.images.length > 1 && (
                                <div className="absolute bottom-6 left-0 right-0 flex justify-center gap-2 z-10">
                                    {product.images.map((_, idx) => (
                                        <button 
                                            key={idx} 
                                            onClick={() => scrollToImage(idx)}
                                            className={`h-1.5 rounded-full transition-all duration-500 ${selectedImageIndex === idx ? 'bg-primary w-6' : 'bg-gray-300 dark:bg-gray-600 w-1.5'}`}
                                        />
                                    ))}
                                </div>
                            )}

                            {product.stock === 0 && (
                                <div className="absolute top-6 left-6 bg-red-600 text-white text-[10px] font-black px-4 py-1.5 rounded-full shadow-lg z-10 uppercase tracking-widest">
                                    Sold Out
                                </div>
                            )}
                        </div>

                        {product.images.length > 1 && (
                            <div className="flex gap-3 overflow-x-auto hide-scrollbar pb-1">
                                {product.images.map((img, idx) => (
                                    <div 
                                        key={idx} 
                                        onClick={() => scrollToImage(idx)}
                                        className={`w-20 h-20 rounded-2xl border-2 cursor-pointer overflow-hidden flex-shrink-0 transition-all ${selectedImageIndex === idx ? 'border-primary shadow-lg shadow-primary/20 scale-105' : 'border-gray-100 dark:border-gray-800 hover:border-gray-300'}`}
                                    >
                                        <img src={img} className="w-full h-full object-cover" />
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Right: Product Info */}
                    <div className="p-6 md:p-10 lg:border-l border-gray-100 dark:border-gray-800 flex flex-col">
                        <div className="mb-6">
                            <Badge color="violet" className="mb-3">{product.category}</Badge>
                            <h1 className="text-3xl md:text-4xl font-display font-black text-gray-900 dark:text-white leading-tight tracking-tight">{product.title}</h1>
                            <div className="flex items-center gap-3 mt-4">
                                <div className="flex text-yellow-400 text-sm">
                                    {[1,2,3,4,5].map(i => <i key={i} className={`fa-solid fa-star ${i <= (product.rating||0) ? '' : 'text-gray-200 dark:text-gray-700'}`}></i>)}
                                </div>
                                <span className="text-xs text-gray-500 dark:text-gray-400 font-bold uppercase tracking-tighter">Verified Product</span>
                            </div>
                        </div>

                        <div className="bg-gray-50 dark:bg-gray-900/50 rounded-3xl p-6 mb-8 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                            <div>
                                <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mb-1">Current Price</p>
                                <div className="flex items-baseline gap-2">
                                    <span className="text-4xl font-black text-gray-900 dark:text-white">₵{product.price.toFixed(2)}</span>
                                    {product.price > 0 && <span className="text-sm text-gray-400 dark:text-gray-600 line-through">₵{(product.price * 1.25).toFixed(0)}</span>}
                                </div>
                            </div>
                            <div className={`px-4 py-2 rounded-2xl text-xs font-black uppercase tracking-widest ${product.stock > 0 ? 'bg-green-100 text-green-700 dark:bg-green-900/20 dark:text-green-500' : 'bg-red-50 text-red-600'}`}>
                                {product.stock > 0 ? `${product.stock} Units Available` : 'Sold Out'}
                            </div>
                        </div>

                        <div className="mb-8">
                            <h3 className="font-display font-black text-gray-900 dark:text-white text-sm uppercase tracking-widest mb-3">Description</h3>
                            <p className="text-gray-600 dark:text-gray-400 leading-relaxed text-base">
                                {product.description}
                            </p>
                        </div>

                        <div className="mt-auto space-y-6">
                            {/* Actions Group */}
                            <div className="flex flex-wrap gap-4">
                                <div className="flex items-center bg-gray-100 dark:bg-gray-800 rounded-2xl h-14 w-36 px-2">
                                    <button 
                                        onClick={() => handleQuantity(-1)}
                                        disabled={quantity <= 1}
                                        className="w-10 h-10 flex items-center justify-center text-gray-500 hover:text-primary disabled:opacity-30"
                                    >
                                        <i className="fa-solid fa-minus"></i>
                                    </button>
                                    <span className="flex-1 text-center font-black text-lg dark:text-white">{quantity}</span>
                                    <button 
                                        onClick={() => handleQuantity(1)}
                                        disabled={quantity >= product.stock}
                                        className="w-10 h-10 flex items-center justify-center text-gray-500 hover:text-primary disabled:opacity-30"
                                    >
                                        <i className="fa-solid fa-plus"></i>
                                    </button>
                                </div>

                                {whatsappUrl && (
                                    <a 
                                        href={whatsappUrl}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="w-14 h-14 bg-[#25D366] text-white rounded-2xl flex items-center justify-center shadow-lg shadow-green-500/20 hover:scale-105 active:scale-95 transition-all"
                                    >
                                        <i className="fa-brands fa-whatsapp text-2xl"></i>
                                    </a>
                                )}

                                <button 
                                    onClick={handleBuyNow}
                                    disabled={product.stock === 0}
                                    className={`flex-1 min-w-[180px] h-14 rounded-2xl font-black text-white shadow-xl flex items-center justify-center gap-3 transition-all active:scale-95 bg-gradient-to-r from-primary to-primaryDark hover:shadow-glow ${product.stock === 0 ? 'opacity-50 cursor-not-allowed grayscale' : ''}`}
                                >
                                    <i className="fa-solid fa-bolt-lightning"></i> Checkout Now
                                </button>
                            </div>

                            {/* Enhanced Vendor Card */}
                            <div 
                                className="group p-4 bg-white dark:bg-gray-900 border border-gray-100 dark:border-gray-800 rounded-3xl flex items-center gap-4 cursor-pointer hover:border-primary/50 transition-all shadow-sm"
                                onClick={() => navigate(`/store/${vendor?.vendorId}`)}
                            >
                                <Avatar src={vendor?.storeAvatarUrl} name={vendor?.storeName || 'Vendor'} size="lg" className="rounded-2xl border-2 border-primary/10" />
                                <div className="flex-1">
                                    <p className="text-[10px] font-black text-primary uppercase tracking-[0.2em]">Verified Seller</p>
                                    <p className="text-lg font-display font-black text-gray-900 dark:text-white group-hover:text-primary transition-colors">{vendor?.storeName}</p>
                                    <p className="text-xs text-gray-400 font-bold">📍 {vendor?.location}</p>
                                </div>
                                <div className="w-10 h-10 rounded-full bg-gray-50 dark:bg-gray-800 flex items-center justify-center text-gray-400 group-hover:bg-primary group-hover:text-white transition-all">
                                     <i className="fa-solid fa-arrow-right"></i>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Related Products Section */}
                {relatedProducts.length > 0 && (
                    <div className="mt-20">
                        <div className="flex items-center justify-between mb-8">
                            <h3 className="font-display font-black text-2xl text-gray-900 dark:text-white tracking-tight">You May Also Like</h3>
                            <Link to="/buyer/dashboard" className="text-sm font-bold text-primary uppercase tracking-widest hover:underline decoration-2 underline-offset-4">Discover More</Link>
                        </div>

                        {/* Improved Grid for Related Products on Large Screens */}
                        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4 md:gap-6">
                            {relatedProducts.map(rp => (
                                <div 
                                    key={rp.id}
                                    onClick={() => {
                                        navigate(`/buyer/product/${rp.id}`);
                                        window.scrollTo({ top: 0, behavior: 'smooth' });
                                    }}
                                    className="bg-white dark:bg-darkSurface rounded-[2rem] border border-gray-100 dark:border-gray-800 p-3 shadow-card hover:shadow-xl transition-all duration-500 cursor-pointer group"
                                >
                                    <div className="aspect-square bg-gray-50 dark:bg-gray-900 rounded-2xl overflow-hidden mb-4 relative">
                                        <img src={rp.images[0]} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                                        <div className="absolute top-2 right-2 px-3 py-1 bg-white/90 dark:bg-darkBg/90 backdrop-blur-md rounded-full text-xs font-black text-gray-900 dark:text-white shadow-sm border border-black/5 dark:border-white/5">
                                            ₵{rp.price}
                                        </div>
                                    </div>
                                    <h4 className="font-bold text-sm text-gray-900 dark:text-white line-clamp-1 group-hover:text-primary transition-colors px-1">{rp.title}</h4>
                                    <div className="flex items-center justify-between mt-3 px-1">
                                        <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter truncate max-w-[120px]">{rp.category}</span>
                                        <div className="w-8 h-8 rounded-full bg-primary/10 text-primary flex items-center justify-center group-hover:bg-primary group-hover:text-white transition-all">
                                            <i className="fa-solid fa-plus text-[10px]"></i>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export const Cart: React.FC = () => {
    const { cart, removeFromCart, updateCartQuantity, clearCart } = useApp();
    const navigate = useNavigate();

    const subtotal = cart.reduce((s, i) => s + i.product.price * i.quantity, 0);

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-safe">
             <div className="bg-white dark:bg-darkSurface p-4 shadow-sm sticky top-0 z-10 flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <button onClick={() => navigate(-1)} className="dark:text-white"><i className="fa-solid fa-arrow-left"></i></button>
                    <h1 className="text-xl font-bold font-display dark:text-white">My Cart ({cart.length})</h1>
                </div>
                {cart.length > 0 && <button onClick={clearCart} className="text-xs text-red-500 font-bold">Clear All</button>}
             </div>

             <div className="p-4 space-y-4">
                {cart.length === 0 ? (
                    <div className="text-center py-20 text-gray-400 dark:text-gray-500">
                        <i className="fa-solid fa-cart-arrow-down text-4xl mb-4 opacity-20"></i>
                        <p>Your cart is empty.</p>
