export const Checkout: React.FC = () => {
    const { cart, placeOrder, currentUser, signup, login } = useApp();
    const navigate = useNavigate();
    const [method, setMethod] = useState<'delivery' | 'pickup'>('delivery');
    const [isPlacing, setIsPlacing] = useState(false);
    const [guestEmail, setGuestEmail] = useState('');
    const [deliveryFee, setDeliveryFee] = useState(10); 

    useEffect(() => {
        if (method === 'pickup') {
            setDeliveryFee(0);
        } else {
            setDeliveryFee(15.00); 
        }
    }, [method]);

    const handleOrder = async () => {
        if (!currentUser && !guestEmail) { alert("Email required for guest checkout"); return; }

        setIsPlacing(true);

        try {
            if (!currentUser) {
                const shadowPass = 'guest123'; 
                const regRes = await signup(guestEmail, shadowPass, 'Guest User', 'buyer');

                if (!regRes.success) {
                     const loginRes = await login(guestEmail, shadowPass);
                     if (!loginRes.success) {
                         alert("This email is already registered. Please Login first.");
                         setIsPlacing(false);
                         return;
                     }
                }
            }

            await placeOrder(method, deliveryFee);
            setTimeout(() => { 
                setIsPlacing(false); 
                navigate('/buyer/orders'); 
            }, 2000);

        } catch (e) {
            console.error(e);
            setIsPlacing(false);
            alert("Checkout failed. Please try again.");
        }
    };

    const subtotal = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
    const total = subtotal + deliveryFee;

    return (
        <div className="p-4 min-h-screen bg-gray-50 dark:bg-darkBg pb-32 animate-fade-in pb-safe">
            <h1 className="text-2xl font-display font-bold mb-6 dark:text-white">Checkout</h1>

            {!currentUser && (
                <Card className="p-4 mb-4">
                    <h3 className="font-bold text-sm mb-2 dark:text-white">Guest Checkout</h3>
                    <Input label="Email Address" value={guestEmail} onChange={e => setGuestEmail(e.target.value)} placeholder="Enter email for receipt" />
                    <p className="text-xs text-gray-400 dark:text-gray-500 mt-2">We'll create a temporary account for you to track this order.</p>
                </Card>
            )}

            <div className="grid grid-cols-2 gap-4 mb-6">
                <div onClick={() => setMethod('delivery')} className={`p-4 rounded-xl border-2 cursor-pointer text-center transition-all ${method === 'delivery' ? 'border-primary bg-blue-50 dark:bg-primary/10 text-primary dark:text-primaryLight' : 'border-transparent bg-white dark:bg-darkSurface dark:text-white'}`}>
                    <i className="fa-solid fa-motorcycle text-xl mb-2"></i>
                    <p className="font-bold text-sm">Delivery</p>
                    <p className="text-xs opacity-70">₵{deliveryFee}</p>
                </div>
                <div onClick={() => setMethod('pickup')} className={`p-4 rounded-xl border-2 cursor-pointer text-center transition-all ${method === 'pickup' ? 'border-primary bg-blue-50 dark:bg-primary/10 text-primary dark:text-primaryLight' : 'border-transparent bg-white dark:bg-darkSurface dark:text-white'}`}>
                    <i className="fa-solid fa-person-walking text-xl mb-2"></i>
                    <p className="font-bold text-sm">Pickup</p>
                    <p className="text-xs opacity-70">Free</p>
                </div>
            </div>

            <Card className="p-5">
                <h3 className="font-bold mb-4 dark:text-white">Summary</h3>
                <div className="space-y-2">
                    {cart.map(i => <div key={i.productId} className="flex justify-between text-sm dark:text-gray-400"><span>{i.product.title} x{i.quantity}</span><span className="dark:text-white">₵{i.product.price * i.quantity}</span></div>)}
                </div>
                <div className="border-t border-dashed dark:border-gray-800 my-4"></div>
                <div className="flex justify-between text-sm dark:text-gray-400"><span>Subtotal</span><span className="dark:text-white">₵{subtotal.toFixed(2)}</span></div>
                <div className="flex justify-between text-sm dark:text-gray-400"><span>Fee</span><span className="dark:text-white">₵{deliveryFee.toFixed(2)}</span></div>
                <div className="flex justify-between font-bold text-lg mt-2 dark:text-white"><span>Total</span><span>₵{total.toFixed(2)}</span></div>
            </Card>

            <div className="fixed bottom-0 left-0 right-0 p-4 bg-white dark:bg-darkSurface border-t border-gray-100 dark:border-gray-800">
                <Button fullWidth size="lg" onClick={handleOrder} disabled={isPlacing}>
                    {isPlacing ? 'Processing Order...' : `Pay ₵${total.toFixed(2)}`}
                </Button>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { useApp } from '../context';
import { Button, Badge, Card, Input, Avatar, Spinner } from '../components/UI';
import { Product } from '../types';

export const StorePage: React.FC = () => {
    const { vendorId } = useParams<{ vendorId: string }>();
    const navigate = useNavigate();
    const { vendors, products, addToCart, cart, removeFromCart, toggleFavorite, favorites, showToast } = useApp();

    const vendor = vendors.find(v => v.vendorId === vendorId);
    const vendorProducts = products.filter(p => p.vendorId === vendorId && p.status === 'approved');

    if (!vendor) return <div className="p-8 text-center text-gray-500 dark:text-gray-400">Store not found</div>;

    const whatsappUrl = vendor.contactPhone 
        ? `https://wa.me/${vendor.contactPhone.replace(/[^0-9]/g, '').replace(/^0/, '233')}?text=Hi ${vendor.storeName}, I saw your store on LYNQED!`
        : null;

    const handleShare = async () => {
        let shareUrl = window.location.href;

        // Normalize the URL to ensure it is absolute and valid for the native share sheet
        try {
            const urlObj = new URL(window.location.href);
            shareUrl = urlObj.href;
        } catch (e) {
            console.warn("URL normalization failed", e);
        }

        const shareData = {
            title: `LYNQED | ${vendor.storeName}`,
            text: `Check out ${vendor.storeName} on campus!`,
            url: shareUrl
        };

        try {
            // Check if share is supported and if the browser thinks the data is shareable
            if (navigator.share && (typeof navigator.canShare !== 'function' || navigator.canShare(shareData))) {
                await navigator.share(shareData);
            } else {
                throw new Error("Native share not supported or data rejected");
            }
        } catch (err) {
            // If the error is 'AbortError', the user just closed the share sheet. 
            // Otherwise, it's a real failure (like Invalid URL), so we fallback to clipboard.
            if (err instanceof Error && err.name !== 'AbortError') {
                console.error("Share failed, falling back to clipboard:", err);
                try {
                    await navigator.clipboard.writeText(shareUrl);
                    showToast("Link copied to clipboard!", "success");
                } catch (clipboardErr) {
                    showToast("Failed to copy link.", "error");
                }
            }
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-20 animate-fade-in">
            {/* Store Header */}
            <div className="bg-white dark:bg-darkSurface p-6 md:p-10 shadow-sm border-b border-gray-100 dark:border-gray-800">
                <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center md:items-start gap-6">
                     <Avatar src={vendor.storeAvatarUrl} name={vendor.storeName} size="xl" className="md:w-32 md:h-32 rounded-3xl" />
                     <div className="flex-1 text-center md:text-left">
                         <div className="flex items-center justify-center md:justify-start gap-2">
                            <h1 className="text-2xl md:text-3xl font-display font-black text-gray-900 dark:text-white tracking-tight">{vendor.storeName}</h1>
                            {vendor.isApproved && <i className="fa-solid fa-circle-check text-blue-500 text-lg"></i>}
                         </div>
                         <div className="flex items-center justify-center md:justify-start gap-1 text-sm text-gray-500 dark:text-gray-400 mt-2 mb-3">
                             <i className="fa-solid fa-location-dot text-red-500"></i> {vendor.location}
                             <span className="mx-2 opacity-30">•</span>
                             <i className="fa-solid fa-star text-yellow-400"></i> {vendor.rating}
                         </div>
                         <p className="text-gray-600 dark:text-gray-400 max-w-2xl leading-relaxed">{vendor.storeDescription}</p>

                         {/* Actions Wrapper */}
                         <div className="flex flex-wrap items-center justify-center md:justify-start gap-3 mt-6">
                            {whatsappUrl && (
                                <a 
                                    href={whatsappUrl}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="flex items-center justify-center gap-2 bg-[#25D366] text-white px-6 py-3 rounded-2xl text-sm font-bold hover:bg-[#128C7E] transition-all shadow-lg shadow-green-500/20 active:scale-95"
                                >
                                    <i className="fa-brands fa-whatsapp text-lg"></i> Chat on WhatsApp
                                </a>
                            )}
                            <button 
                                onClick={handleShare}
                                className="flex items-center justify-center gap-2 bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 px-6 py-3 rounded-2xl text-sm font-bold hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors border border-gray-200 dark:border-gray-700 active:scale-95"
                            >
                                <i className="fa-solid fa-share-nodes"></i> Share Store
                            </button>
                         </div>
                     </div>
                </div>
            </div>

            {/* Product Grid Section */}
            <div className="max-w-7xl mx-auto p-4 md:p-8">
                <div className="flex items-center gap-3 mb-6">
                    <h2 className="font-display font-black text-gray-900 dark:text-white text-lg uppercase tracking-wider">Catalog</h2>
                    <div className="h-px flex-1 bg-gray-200 dark:bg-gray-800"></div>
                    <Badge color="blue">{vendorProducts.length} Items</Badge>
                </div>

                {vendorProducts.length === 0 ? (
                    <div className="text-center py-24 bg-white dark:bg-darkSurface rounded-[2.5rem] border border-dashed border-gray-200 dark:border-gray-800">
                        <i className="fa-solid fa-box-open text-4xl mb-4 text-gray-200"></i>
                        <p className="text-gray-400 font-medium">No active listings from this vendor yet.</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4 md:gap-6">
                        {vendorProducts.map(product => {
                            const isFav = favorites.includes(product.id);
                            const isInCart = cart.some(item => item.productId === product.id);

                            return (
                                <div 
                                    key={product.id} 
                                    className="bg-white dark:bg-darkSurface rounded-[2rem] overflow-hidden shadow-card hover:shadow-xl transition-all duration-500 group relative flex flex-col h-full cursor-pointer border border-gray-50 dark:border-gray-800/50"
                                    onClick={() => navigate(`/buyer/product/${product.id}`)}
                                >
                                    <div className="aspect-[4/5] w-full relative overflow-hidden bg-gray-50 dark:bg-gray-900">
                                        <img 
                                            src={product.images[0]} 
                                            alt={product.title} 
                                            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" 
                                        />
                                        <button 
                                            className="absolute top-3 right-3 z-10 w-9 h-9 rounded-full bg-white/90 dark:bg-darkBg/90 backdrop-blur-md border border-gray-100 dark:border-gray-800 text-gray-400 hover:text-red-500 flex items-center justify-center transition-all shadow-sm active:scale-90"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                toggleFavorite(product.id);
                                            }}
                                        >
                                            <i className={`${isFav ? 'fa-solid text-red-500' : 'fa-regular'} fa-heart text-sm`}></i>
                                        </button>
                                        {product.stock === 0 && (
                                            <div className="absolute inset-0 bg-black/50 backdrop-blur-[2px] flex items-center justify-center z-10">
                                                <span className="bg-black/80 text-white text-[10px] px-3 py-1.5 rounded-full font-black uppercase tracking-widest border border-white/20">Sold Out</span>
                                            </div>
                                        )}
                                    </div>
                                    <div className="p-4 flex flex-col justify-between flex-grow">
                                        <div className="mb-2">
                                            <h3 className="text-sm text-gray-800 dark:text-white font-bold leading-snug line-clamp-2 group-hover:text-primary transition-colors">{product.title}</h3>
                                        </div>
                                        <div className="flex items-center justify-between pt-2">
                                            <span className="text-base font-black text-gray-900 dark:text-white">₵{product.price.toFixed(2)}</span>
                                            <button 
                                                className={`w-9 h-9 rounded-full flex items-center justify-center text-white transition-all shadow-md active:scale-90 ${product.stock === 0 ? 'bg-gray-200 dark:bg-gray-800 cursor-not-allowed text-gray-400' : isInCart ? 'bg-green-500' : 'bg-gray-900 dark:bg-white dark:text-black hover:bg-primary hover:text-white'}`}
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (product.stock > 0) {
                                                        isInCart ? removeFromCart(product.id) : addToCart(product);
                                                    }
                                                }}
                                                disabled={product.stock === 0}
                                            >
                                                <i className={`fa-solid ${isInCart ? 'fa-check' : 'fa-plus'} text-xs`}></i>
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
};

export const ProductDetail: React.FC = () => {
