export interface ToastMessage {
    message: string;
    type: 'success' | 'error' | 'info';
}

export const Toast: React.FC<{ toast: ToastMessage | null; onClose: () => void }> = ({ toast, onClose }) => {
    const [visible, setVisible] = useState(false);

    useEffect(() => {
        if (toast) {
            setVisible(true);
            const timer = setTimeout(() => {
                setVisible(false);
                setTimeout(onClose, 300); // Wait for fade-out animation
            }, 3000);
            return () => clearTimeout(timer);
        }
    }, [toast, onClose]);

    if (!toast) return null;

    const icons = {
        success: 'circle-check',
        error: 'circle-exclamation',
        info: 'circle-info'
    };

    const colors = {
        success: 'bg-green-600 text-white shadow-green-500/30',
        error: 'bg-red-500 text-white shadow-red-500/30',
        info: 'bg-blue-600 text-white shadow-blue-500/30'
    };

    return (
        <div className={`fixed top-6 left-1/2 transform -translate-x-1/2 z-[9999] transition-all duration-500 ease-out ${visible ? 'translate-y-0 opacity-100' : '-translate-y-8 opacity-0 pointer-events-none'}`}>
            <div className={`flex items-center gap-3 px-6 py-3.5 rounded-full shadow-2xl ${colors[toast.type]} min-w-[200px] max-w-xs border border-white/20 backdrop-blur-sm`}>
                <i className={`fa-solid fa-${icons[toast.type]} text-lg`}></i>
                <span className="text-sm font-bold tracking-wide whitespace-nowrap">{toast.message}</span>
            </div>
        </div>
    );
};

