);

// --- Toast Notification ---
export const Toast: React.FC<{ toast: ToastMessage | null; onClose: () => void }> = ({ toast, onClose }) => {
    const [visible, setVisible] = useState(false);
    const [currentId, setCurrentId] = useState<number | null>(null);

    useEffect(() => {
        if (toast && toast.id !== currentId) {
            // New toast detected (even if message is same)
            setCurrentId(toast.id);
            setVisible(false); // Reset animation state

            const showTimeout = setTimeout(() => {
                setVisible(true);
            }, 50);

            const hideTimeout = setTimeout(() => {
                setVisible(false);
                setTimeout(onClose, 300); // Wait for exit animation
            }, 3000);

            return () => {
                clearTimeout(showTimeout);
                clearTimeout(hideTimeout);
            };
        }
    }, [toast, onClose, currentId]);

    if (!toast) return null;

    const icons = {
        success: 'circle-check',
        error: 'circle-exclamation',
        info: 'circle-info'
    };

    const colors = {
        success: 'bg-green-600 text-white shadow-green-500/30',
        error: 'bg-red-500 text-white shadow-red-500/30',
        info: 'bg-blue-600 text-white shadow-blue-500/30'
    };

    return (
        <div className={`fixed top-6 left-1/2 transform -translate-x-1/2 z-[9999] transition-all duration-500 ease-out pointer-events-none ${visible ? 'translate-y-0 opacity-100' : '-translate-y-8 opacity-0'}`}>
            <div className={`flex items-center gap-3 px-6 py-3.5 rounded-full shadow-2xl ${colors[toast.type]} min-w-[200px] max-w-xs border border-white/20 backdrop-blur-sm pointer-events-auto`}>
                <i className={`fa-solid fa-${icons[toast.type]} text-lg`}></i>
                <span className="text-sm font-bold tracking-wide whitespace-nowrap">{toast.message}</span>
            </div>
        </div>
    );
};

