// --- Toast Notification ---
export const Toast: React.FC<{ toast: ToastMessage | null; onClose: () => void }> = ({ toast, onClose }) => {
    const [visible, setVisible] = useState(false);

    useEffect(() => {
        if (toast) {
            // Tiny delay to trigger CSS entry transition
            const entryTimer = setTimeout(() => setVisible(true), 10);

            const timer = setTimeout(() => {
                setVisible(false);
                setTimeout(onClose, 400); // Allow exit animation to finish
            }, 3000);

            return () => {
                clearTimeout(entryTimer);
                clearTimeout(timer);
            };
        }
    }, [toast, onClose]);

    if (!toast) return null;

    const icons = {
        success: 'circle-check',
        error: 'circle-exclamation',
        info: 'circle-info'
    };

    const colors = {
        success: 'bg-green-600 text-white shadow-green-500/30',
        error: 'bg-red-500 text-white shadow-red-500/30',
        info: 'bg-blue-600 text-white shadow-blue-500/30'
    };

    return (
        <div className={`fixed top-8 left-1/2 -translate-x-1/2 z-[9999] transition-all duration-500 ease-out pointer-events-none ${visible ? 'translate-y-0 opacity-100 scale-100' : '-translate-y-12 opacity-0 scale-90'}`}>
            <div className={`flex items-center gap-3 px-6 py-4 rounded-full shadow-2xl ${colors[toast.type]} min-w-[240px] max-w-sm border border-white/20 backdrop-blur-md pointer-events-auto`}>
                <i className={`fa-solid fa-${icons[toast.type]} text-xl`}></i>
                <span className="text-sm font-bold tracking-tight whitespace-nowrap">{toast.message}</span>
                <button onClick={() => setVisible(false)} className="ml-auto pl-2 opacity-50 hover:opacity-100 transition-opacity">
                    <i className="fa-solid fa-xmark text-xs"></i>
                </button>
            </div>
        </div>
    );
};

