// --- Toast Notification ---
export const Toast: React.FC<{ toast: ToastMessage | null; onClose: () => void }> = ({ toast, onClose }) => {
    const navigate = useNavigate();
    const [isVisible, setIsVisible] = useState(false);

    // Using a ref to track the current timeout and clear it if a new toast arrives
    const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    useEffect(() => {
        if (toast) {
            // New toast arrived!
            // 1. Clear any existing timeout
            if (timeoutRef.current) clearTimeout(timeoutRef.current);

            // 2. Trigger "Visible" state with a slight flicker to re-trigger animation if already visible
            setIsVisible(false); 
            const flickerTimer = setTimeout(() => {
                setIsVisible(true);

                // 3. Set standard 3 second timer
                timeoutRef.current = setTimeout(() => {
                    setIsVisible(false);
                    // 4. Wait for exit animation then clear from context
                    setTimeout(onClose, 300);
                }, 3000);
            }, 50);

            return () => {
                clearTimeout(flickerTimer);
                if (timeoutRef.current) clearTimeout(timeoutRef.current);
            };
        } else {
            setIsVisible(false);
        }
    }, [toast?.id, onClose]);

    if (!toast) return null;

    const icons = {
        success: 'circle-check',
        error: 'circle-exclamation',
        info: 'circle-info'
    };

    const colors = {
        success: 'bg-green-600 text-white shadow-green-500/40',
        error: 'bg-red-500 text-white shadow-red-500/40',
        info: 'bg-blue-600 text-white shadow-blue-500/40'
    };

    const isWishlistAction = toast.message.toLowerCase().includes('wishlist');

    return (
        <div 
            className={`fixed top-6 left-1/2 transform -translate-x-1/2 z-[9999] transition-all duration-300 ease-out pointer-events-none ${isVisible ? 'translate-y-0 opacity-100' : '-translate-y-8 opacity-0'}`}
        >
            <div className={`flex items-center gap-4 px-6 py-4 rounded-full shadow-2xl ${colors[toast.type]} min-w-[280px] max-w-sm border border-white/20 backdrop-blur-md pointer-events-auto`}>
                <i className={`fa-solid fa-${icons[toast.type]} text-xl`}></i>
                <div className="flex-1">
                   <p className="text-xs font-bold leading-tight tracking-wide">{toast.message}</p>
                </div>
                {isWishlistAction && (
                    <button 
                        onClick={() => {
                            setIsVisible(false);
                            onClose();
                            navigate('/buyer/wishlist');
                        }}
                        className="text-[10px] font-black uppercase tracking-widest bg-white/20 px-3 py-1.5 rounded-full hover:bg-white/30 transition-colors border border-white/10 ml-2"
                    >
                        View
                    </button>
                )}
            </div>
        </div>
    );
};

