// --- Toast Notification ---
export const Toast: React.FC<{ toast: ToastMessage | null; onClose: () => void }> = ({ toast, onClose }) => {
    const navigate = useNavigate();
    const [isVisible, setIsVisible] = useState(false);
    const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    // Watch for new toasts by ID
    useEffect(() => {
        if (toast) {
            // 1. Clear any existing timers immediately
            if (closeTimerRef.current) clearTimeout(closeTimerRef.current);

            // 2. Trigger appearance
            setIsVisible(true);

            // 3. Set a strict 3-second timer to close
            closeTimerRef.current = setTimeout(() => {
                setIsVisible(false);
                // Allow exit animation to finish before calling context-level onClose
                setTimeout(() => {
                  onClose();
                }, 300);
            }, 3000);
        } else {
            setIsVisible(false);
        }

        return () => {
          if (closeTimerRef.current) clearTimeout(closeTimerRef.current);
        };
    }, [toast?.id]); // ONLY watch the unique ID

    if (!toast) return null;

    const icons = {
        success: 'circle-check',
        error: 'circle-exclamation',
        info: 'circle-info'
    };

    const colors = {
        success: 'bg-green-600 text-white shadow-green-500/40',
        error: 'bg-red-500 text-white shadow-red-500/40',
        info: 'bg-blue-600 text-white shadow-blue-500/40'
    };

    const isWishlistAction = toast.message.toLowerCase().includes('wishlist') || toast.message.toLowerCase().includes('saved');

    return (
        <div 
            className={`fixed top-6 left-1/2 transform -translate-x-1/2 z-[9999] transition-all duration-300 ease-out pointer-events-none ${isVisible ? 'translate-y-0 opacity-100 scale-100' : '-translate-y-12 opacity-0 scale-90'}`}
        >
            <div className={`flex items-center gap-4 px-6 py-4 rounded-full shadow-2xl ${colors[toast.type]} min-w-[280px] max-w-sm border border-white/20 backdrop-blur-md pointer-events-auto`}>
                <i className={`fa-solid fa-${icons[toast.type]} text-xl`}></i>
                <div className="flex-1">
                   <p className="text-xs font-bold leading-tight tracking-wide">{toast.message}</p>
                </div>
                {isWishlistAction && (
                    <button 
                        onClick={() => {
                            setIsVisible(false);
                            onClose();
                            navigate('/buyer/wishlist');
                        }}
                        className="text-[10px] font-black uppercase tracking-widest bg-white/20 px-3 py-1.5 rounded-full hover:bg-white/30 transition-colors border border-white/10 ml-2"
                    >
                        View
                    </button>
                )}
            </div>
        </div>
    );
};

