                                <div className={`w-full h-full flex items-center justify-center bg-gray-200 dark:bg-darkSurface text-gray-500 dark:text-gray-400`}>
                                    <i className={`fa-solid fa-${cat.icon} text-lg`}></i>
                                </div>
                            )}
                        </div>
                        <span className={`text-[10px] font-bold text-center w-full uppercase ${isSelected ? 'text-primary' : 'text-gray-500 dark:text-gray-400'}`}>
                            {cat.name}
                        </span>
                    </div>
                );
            })}
        </div>
      </div>

      {/* COMPACT SEAMLESS INFINITE LOOP TRENDING SECTION */}
      {trendingProducts.length > 0 && (
          <div className="relative bg-white/40 dark:bg-darkSurface/20 py-4 border-y border-gray-100 dark:border-gray-800">
            <div className="flex justify-between items-center mb-2 px-4">
                <h3 className="font-display font-black text-gray-900 dark:text-white text-[9px] uppercase tracking-[0.2em] flex items-center gap-1.5 opacity-80">
                    <i className="fa-solid fa-fire text-orange-500 text-[10px]"></i> Sponsored Spotlight
                </h3>
                <div className="flex items-center gap-1 opacity-30">
                    <span className="text-[7px] font-black uppercase tracking-[0.2em]">Partner Content</span>
                </div>
            </div>

            {/* Carousel Container - Native Scroll + Auto Scroll Support */}
            <div className="overflow-x-auto hide-scrollbar relative w-full group select-none">
                {/* The Moving Track: Double the array for a truly seamless loop */}
                <div className="flex w-fit animate-scroll pause-on-hover py-1">
                    {[...trendingProducts, ...trendingProducts].map((p, idx) => (
                        <div 
                            key={`${p.id}-${idx}`}
                            onClick={() => navigate(`/buyer/product/${p.id}`)}
                            className="mx-1.5 w-[110px] md:w-[150px] bg-white dark:bg-darkSurface rounded-xl p-1 shadow-sm border border-gray-100 dark:border-gray-800 active:scale-95 transition-all cursor-pointer flex flex-col flex-shrink-0"
                        >
                            <div className="aspect-square rounded-lg overflow-hidden mb-1.5 bg-gray-50 dark:bg-gray-900 flex-shrink-0 relative">
                                <img src={p.images[0]} className="w-full h-full object-cover" alt={p.title} />
                                <div className="absolute top-1 right-1 bg-black/80 backdrop-blur-md text-white text-[8px] px-1.5 py-0.5 rounded font-black uppercase shadow-sm border border-white/10">
                                   ₵{p.price}
