export const VendorOrders: React.FC = () => {
    const { orders, updateOrderStatus, vendors, currentUser, refreshData } = useApp();
    const [filter, setFilter] = useState<'all' | 'active' | 'completed'>('active');
    const [isRefreshing, setIsRefreshing] = useState(false);

    const currentVendor = vendors.find(v => v.userId === currentUser?.id);
    const vendorId = currentVendor?.vendorId;

    const myOrders = useMemo(() => orders.filter(o => o.vendorId === vendorId), [orders, vendorId]);

    const handleRefresh = async () => {
        setIsRefreshing(true);
        await refreshData();
        setIsRefreshing(false);
    };

    useEffect(() => { 
        handleRefresh(); 
    }, []);

    const filteredOrders = myOrders.filter(o => {
        if (filter === 'all') return true;
        if (filter === 'active') return ['placed', 'received', 'preparing', 'ready_for_pickup', 'assigned'].includes(o.status);
        if (filter === 'completed') return ['picked_up', 'in_route', 'delivered', 'declined', 'cancelled'].includes(o.status);
        return true;
    }).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    const handleStatusChange = async (e: React.MouseEvent, orderId: string, newStatus: OrderStatus) => {
        e.stopPropagation();
        await updateOrderStatus(orderId, newStatus);
    };

    const getNextAction = (status: OrderStatus, deliveryOption: 'delivery' | 'pickup') => {
        if (status === 'placed') return { label: 'Accept Order', next: 'received' as OrderStatus, icon: 'check', btnVariant: 'primary' as const };
        if (status === 'received') return { label: 'Start Preparing', next: 'preparing' as OrderStatus, icon: 'fire-burner', btnVariant: 'primary' as const };
        if (status === 'preparing') {
             return deliveryOption === 'delivery' 
                ? { label: 'Ready for Driver', next: 'ready_for_pickup' as OrderStatus, icon: 'box', btnVariant: 'primary' as const }
                : { label: 'Ready for Pickup', next: 'ready_for_pickup' as OrderStatus, icon: 'box', btnVariant: 'primary' as const };
        }
        if (status === 'ready_for_pickup' && deliveryOption === 'pickup') {
             return { label: 'Picked Up', next: 'delivered' as OrderStatus, icon: 'check', btnVariant: 'success' as const };
        }
        return null;
    };

    return (
        <div className="p-4 min-h-screen bg-gray-50 dark:bg-darkBg pb-24 animate-fade-in pb-safe">
            <div className="mb-4 flex flex-col gap-2">
                <div className="flex justify-between items-center">
                    <h1 className="text-xl font-bold text-gray-900 dark:text-white">Orders Management</h1>
                    <Button size="sm" variant="outline" onClick={handleRefresh} icon={isRefreshing ? 'spinner' : 'rotate'}>
                        {isRefreshing ? 'Checking...' : 'Check Orders'}
                    </Button>
                </div>
            </div>

            <div className="flex gap-2 mb-6">
                {['active', 'completed', 'all'].map(f => (
                    <button key={f} onClick={() => setFilter(f as any)} className={`px-5 py-2 rounded-full text-xs font-bold capitalize transition-all ${filter === f ? 'bg-gray-900 dark:bg-white text-white dark:text-gray-900' : 'bg-white dark:bg-darkSurface text-gray-500 dark:text-gray-400 border border-gray-100 dark:border-gray-800'}`}>{f}</button>
                ))}
            </div>

            <div className="space-y-4">
                {filteredOrders.length === 0 ? <p className="text-center py-10 text-gray-400 dark:text-gray-500">No orders found.</p> : 
                    filteredOrders.map(order => {
                        const nextAction = getNextAction(order.status, order.deliveryOption);
                        return (
                            <Card key={order.id} className="p-5">
                                <div className="flex justify-between items-start mb-4 border-b border-gray-50 dark:border-gray-800 pb-3">
                                    <div>
                                        <span className="font-bold text-gray-900 dark:text-white">#{order.id.slice(-4)}</span>
                                        <Badge color="blue" className="ml-2">{order.deliveryOption}</Badge>
                                        <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">{new Date(order.createdAt).toLocaleDateString()}</p>
                                    </div>
                                    <div className="text-right">
                                        <span className="block font-bold text-primary dark:text-primaryLight">₵{order.total.toFixed(2)}</span>
                                        <span className="text-[10px] font-bold uppercase text-blue-500 dark:text-blue-400">{order.status.replace('_', ' ')}</span>
                                    </div>
                                </div>
                                <div className="space-y-2 mb-4 bg-gray-50 dark:bg-darkBg p-3 rounded-xl">
                                    {order.items.map((item, idx) => (
                                        <div key={idx} className="flex justify-between text-sm dark:text-gray-300"><span className="font-medium">{item.quantity}x {item.product.title}</span></div>
                                    ))}
                                </div>
                                <div className="flex justify-end gap-2">
                                    {['placed', 'received', 'preparing'].includes(order.status) && <Button size="sm" variant="danger" onClick={(e) => handleStatusChange(e, order.id, 'declined')}>Decline</Button>}
                                    {nextAction && <Button size="sm" variant={nextAction.btnVariant} onClick={(e) => handleStatusChange(e, order.id, nextAction.next)} icon={nextAction.icon}>{nextAction.label}</Button>}
                                    {order.status === 'ready_for_pickup' && order.deliveryOption === 'delivery' && <span className="text-xs text-gray-400 dark:text-gray-500 italic py-2">Waiting for driver...</span>}
                                </div>
                            </Card>
                        );
                    })
                }
            </div>
        </div>
    );
};

const ProductForm: React.FC<{
  initialData?: Partial<Product>;
  onSubmit: (data: any) => Promise<void>;
  isLoading?: boolean;
}> = ({ initialData, onSubmit, isLoading }) => {
  const { uploadFile, showToast } = useApp();
  const [formData, setFormData] = useState({
    title: initialData?.title || '',
    description: initialData?.description || '',
    price: initialData?.price || 0,
    category: initialData?.category || 'Food',
    customCategory: '',
    stock: initialData?.stock || 1,
    location: initialData?.location || '',
    contactPhone: initialData?.contactPhone || '',
  });

  const [images, setImages] = useState<string[]>(initialData?.images || []);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
          setIsUploading(true);
          const files = Array.from(e.target.files);
          const newImageUrls: string[] = [];

          for (const file of files) {
              if (file.size > 5 * 1024 * 1024) {
                  showToast(`File ${file.name} is too large (max 5MB)`, 'error');
                  continue;
              }
              const url = await uploadFile(file, 'products');
              if (url) newImageUrls.push(url);
          }

          setImages(prev => [...prev, ...newImageUrls]);
          setIsUploading(false);
          if(fileInputRef.current) fileInputRef.current.value = '';
      }
  };

  const removeImage = (index: number) => {
      setImages(images.filter((_, i) => i !== index));
  };

  const moveImage = (index: number, direction: 'up' | 'down') => {
      const newImages = [...images];
      const targetIndex = direction === 'up' ? index - 1 : index + 1;
      if (targetIndex >= 0 && targetIndex < newImages.length) {
          [newImages[index], newImages[targetIndex]] = [newImages[targetIndex], newImages[index]];
          setImages(newImages);
      }
  };

  const handleSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      const finalCategory = formData.category === 'OTHER' ? formData.customCategory : formData.category;

      onSubmit({
          ...formData,
          category: finalCategory,
          images
      });
  };

  const isCustomCat = initialData?.category && !CATEGORIES.some(c => c.name === initialData.category);
  useEffect(() => {
      if (isCustomCat && initialData?.category) {
          setFormData(prev => ({...prev, category: 'OTHER', customCategory: initialData.category!}));
      }
  }, [isCustomCat]);

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-4">
            <div>
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-2">Product Images</label>
                <div className="grid grid-cols-3 gap-2 mb-2">
                    {images.map((img, idx) => (
                        <div key={idx} className="relative aspect-square rounded-xl overflow-hidden group bg-gray-100 dark:bg-darkBg border border-gray-200 dark:border-gray-800">
                            <img src={img} className="w-full h-full object-cover" />
                            <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-2">
                                <button type="button" onClick={() => removeImage(idx)} className="text-white hover:text-red-400"><i className="fa-solid fa-trash"></i></button>
                                <div className="flex gap-2">
                                    {idx > 0 && <button type="button" onClick={() => moveImage(idx, 'up')} className="text-white"><i className="fa-solid fa-arrow-left"></i></button>}
                                    {idx < images.length - 1 && <button type="button" onClick={() => moveImage(idx, 'down')} className="text-white"><i className="fa-solid fa-arrow-right"></i></button>}
                                </div>
                            </div>
                            {idx === 0 && <span className="absolute bottom-0 left-0 right-0 bg-primary text-white text-[9px] font-bold text-center py-0.5">Cover</span>}
                        </div>
                    ))}
                    <div 
                        onClick={() => !isUploading && fileInputRef.current?.click()}
                        className={`aspect-square rounded-xl border-2 border-dashed border-gray-300 dark:border-gray-700 flex flex-col items-center justify-center text-gray-400 dark:text-gray-500 hover:border-primary hover:text-primary cursor-pointer transition-colors bg-gray-50 dark:bg-darkBg/50 ${isUploading ? 'opacity-50 cursor-wait' : ''}`}
                    >
                        {isUploading ? (
                             <i className="fa-solid fa-spinner fa-spin text-xl mb-1"></i>
                        ) : (
                             <i className="fa-solid fa-cloud-arrow-up text-xl mb-1"></i>
                        )}
                        <span className="text-[10px] font-bold">{isUploading ? 'Uploading' : 'Upload'}</span>
                    </div>
                </div>
                <input type="file" ref={fileInputRef} hidden multiple accept="image/*" onChange={handleImageUpload} />
            </div>

            <Input label="Product Title" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} required placeholder="e.g. Spicy Jollof Rice" />

            <div className="grid grid-cols-2 gap-4">
                <Input label="Price (GHS)" type="number" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} required />
                <Input label="Stock" type="number" value={formData.stock} onChange={e => setFormData({...formData, stock: parseInt(e.target.value)})} required />
            </div>

            <div>
                 <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-2 ml-1">Category</label>
                 <select 
                    className="block w-full rounded-2xl border-transparent bg-white dark:bg-darkSurface shadow-sm ring-1 ring-gray-100 dark:ring-gray-800 py-3.5 px-4 text-gray-900 dark:text-white focus:border-primary focus:ring-primary/20 text-sm mb-2 outline-none"
                    value={formData.category}
                    onChange={e => setFormData({...formData, category: e.target.value})}
                 >
                     {CATEGORIES.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                     <option value="OTHER">Other (Custom)</option>
                 </select>
                 {formData.category === 'OTHER' && (
                     <Input placeholder="Enter category name" value={formData.customCategory} onChange={e => setFormData({...formData, customCategory: e.target.value})} />
                 )}
            </div>

            <div>
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-2 ml-1">Description</label>
                <textarea 
                    className="block w-full rounded-2xl border-transparent bg-white dark:bg-darkSurface shadow-sm ring-1 ring-gray-100 dark:ring-gray-800 py-3 px-4 text-gray-900 dark:text-white placeholder-gray-400 focus:border-primary focus:ring-2 focus:ring-primary/20 transition-all text-sm h-32 outline-none"
                    value={formData.description}
                    onChange={e => setFormData({...formData, description: e.target.value})}
                    required
                ></textarea>
            </div>

            <Input label="Precise Location (for the Map)" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} placeholder="e.g. Jean Nelson Hall, Room 402" />
            <Input label="Contact Phone" value={formData.contactPhone} onChange={e => setFormData({...formData, contactPhone: e.target.value})} placeholder="050..." />
        </div>

        <Button fullWidth size="lg" type="submit" disabled={isLoading || isUploading}>{isLoading ? 'Saving...' : 'Save Product'}</Button>
    </form>
  );
};

