  const { currentUser, currentRole, logout, cart, unreadCount } = useApp();
  const navigate = useNavigate();
  const location = useLocation();
  const [showDropdown, setShowDropdown] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);

  // Hide on auth pages
  const isAuthPage = location.pathname === '/' || location.pathname.startsWith('/auth') || location.pathname === '/forgot-password' || location.pathname === '/update-password';
  if (isAuthPage) return null;

  const mainRoutes = ['/', '/login', '/buyer/dashboard', '/vendor/dashboard', '/admin/dashboard', '/delivery/dashboard'];
  const showBackButton = !mainRoutes.includes(location.pathname);

  // Desktop Nav Links Helper - Clean Text Style
  const NavLink = ({ to, label }: { to: string, label: string }) => (
      <Link to={to} className={`text-sm font-semibold transition-all px-4 py-2 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-800 ${location.pathname === to ? 'text-primary' : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white'}`}>
          {label}
      </Link>
  );

  return (
    <nav className="sticky top-0 z-40 w-full glass border-b border-white/20 dark:border-white/5">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-20 items-center relative">

          {/* Left: Logo & Back Button */}
          <div className="flex items-center gap-4 flex-shrink-0">
             {showBackButton && (
                 <button 
                    onClick={() => navigate(-1)} 
                    className="md:hidden w-10 h-10 flex items-center justify-center rounded-full bg-white/80 dark:bg-darkSurface/80 hover:bg-white dark:hover:bg-darkSurface border border-gray-100 dark:border-gray-800 text-gray-700 dark:text-gray-300 transition-all shadow-sm active:scale-95"
                 >
                     <i className="fa-solid fa-arrow-left text-sm"></i>
                 </button>
             )}

             {/* Logo */}
             <div className="flex items-center gap-3 cursor-pointer group" onClick={() => navigate('/')}>
                <img 
                  src={LOGO_URL} 
                  alt="LYNQED" 
                  className="h-16 w-16 rounded-full object-cover border-2 border-gray-100 dark:border-gray-800 bg-white dark:bg-darkSurface shadow-md group-hover:scale-110 transition-transform p-0.5" 
                />
                <span className="text-2xl font-display font-extrabold text-gray-900 dark:text-white tracking-tight">LYNQED</span>
             </div>
          </div>

          {/* Center: Desktop Navigation Links (Text Only) */}
          {currentUser && (
             <div className="hidden md:flex absolute left-1/2 transform -translate-x-1/2 items-center gap-6">
