import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '../context';
import { Card, Badge, Avatar } from './UI';
import { Notification } from '../types';

interface NotificationCenterProps {
    isOpen: boolean;
    onClose: () => void;
}

export const NotificationCenter: React.FC<NotificationCenterProps> = ({ isOpen, onClose }) => {
    const { notifications, markNotificationRead, markAllNotificationsRead, deleteNotification, unreadCount } = useApp();
    const navigate = useNavigate();
    const [filter, setFilter] = useState<'all' | 'unread'>('all');

    const filtered = notifications.filter(n => filter === 'all' || !n.isRead);

    const handleAction = (n: Notification) => {
        if (!n.isRead) markNotificationRead(n.id);

        onClose();
        if (n.relatedId) {
            if (n.type === 'order_update' || n.type === 'new_order' || n.type === 'delivery') {
                navigate(`/buyer/orders`); // Logic can be refined for vendor orders
            } else if (n.type === 'approval') {
                navigate(`/vendor/products`);
            }
        }
    };

    const getIcon = (type: string) => {
        switch(type) {
            case 'order_update': return { icon: 'box', color: 'text-blue-500 bg-blue-50 dark:bg-blue-900/20' };
            case 'new_order': return { icon: 'shopping-cart', color: 'text-green-500 bg-green-50 dark:bg-green-900/20' };
            case 'delivery': return { icon: 'motorcycle', color: 'text-primary bg-indigo-50 dark:bg-indigo-900/20' };
            case 'approval': return { icon: 'circle-check', color: 'text-emerald-500 bg-emerald-50 dark:bg-emerald-900/20' };
            case 'promotion': return { icon: 'fire', color: 'text-orange-500 bg-orange-50 dark:bg-orange-900/20' };
            default: return { icon: 'bell', color: 'text-gray-500 bg-gray-50 dark:bg-gray-800' };
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex justify-end">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm animate-fade-in" onClick={onClose}></div>

            <div className="relative w-full max-w-md h-full bg-white dark:bg-darkSurface shadow-2xl flex flex-col animate-slide-left border-l border-white/10">
                {/* Header */}
                <div className="p-6 border-b border-gray-100 dark:border-gray-800 flex items-center justify-between">
                    <div>
                        <h2 className="text-xl font-display font-black text-gray-900 dark:text-white">Notifications</h2>
                        <p className="text-xs text-gray-500 font-bold uppercase tracking-widest mt-1">
                            {unreadCount} UNREAD ALERTS
                        </p>
                    </div>
                    <div className="flex gap-2">
                        {unreadCount > 0 && (
                            <button 
                                onClick={markAllNotificationsRead}
                                className="text-[10px] font-black uppercase text-primary hover:underline"
                            >
                                Read All
                            </button>
                        )}
                        <button onClick={onClose} className="w-8 h-8 rounded-full bg-gray-50 dark:bg-gray-800 flex items-center justify-center text-gray-400">
                            <i className="fa-solid fa-xmark"></i>
                        </button>
                    </div>
                </div>

                {/* Filters */}
                <div className="px-6 py-3 flex gap-2 overflow-x-auto hide-scrollbar">
                    {['all', 'unread'].map(f => (
                        <button 
                            key={f}
                            onClick={() => setFilter(f as any)}
                            className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${filter === f ? 'bg-primary text-white' : 'bg-gray-50 dark:bg-gray-800 text-gray-400'}`}
                        >
                            {f}
                        </button>
                    ))}
                </div>

                {/* List */}
                <div className="flex-1 overflow-y-auto p-4 space-y-3">
                    {filtered.length === 0 ? (
                        <div className="h-full flex flex-col items-center justify-center text-center opacity-30 px-10">
                            <i className="fa-solid fa-bell-slash text-4xl mb-4"></i>
                            <p className="text-sm font-bold">You're all caught up!</p>
                            <p className="text-xs mt-2">New campus updates will appear here.</p>
                        </div>
                    ) : (
                        filtered.map(n => {
                            const style = getIcon(n.type);
                            return (
                                <div 
                                    key={n.id}
                                    onClick={() => handleAction(n)}
                                    className={`p-4 rounded-2xl border transition-all cursor-pointer group relative ${n.isRead ? 'bg-white dark:bg-darkSurface border-gray-100 dark:border-gray-800 opacity-60' : 'bg-indigo-50/50 dark:bg-primary/10 border-primary/20 shadow-sm'}`}
                                >
                                    <div className="flex gap-4">
                                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 ${style.color}`}>
                                            <i className={`fa-solid fa-${style.icon}`}></i>
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className="flex justify-between items-start mb-1">
                                                <h4 className={`text-sm font-bold truncate ${n.isRead ? 'text-gray-700 dark:text-gray-300' : 'text-gray-900 dark:text-white'}`}>{n.title}</h4>
                                                <span className="text-[8px] font-black text-gray-400 uppercase whitespace-nowrap ml-2">
                                                    {new Date(n.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                </span>
                                            </div>
                                            <p className="text-xs text-gray-500 dark:text-gray-400 line-clamp-2 leading-relaxed">
                                                {n.message}
                                            </p>
                                        </div>
                                    </div>
                                    {!n.isRead && <div className="absolute top-4 right-4 w-2 h-2 bg-primary rounded-full"></div>}

                                    <button 
                                        onClick={(e) => { e.stopPropagation(); deleteNotification(n.id); }}
                                        className="absolute bottom-2 right-2 p-2 opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-500 transition-opacity"
                                    >
                                        <i className="fa-solid fa-trash-can text-[10px]"></i>
                                    </button>
                                </div>
                            );
                        })
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
