      if (isRemoving) {
          setFavorites(prev => prev.filter(i => i !== pid));
          showToast(`${name} removed`, 'info');
      } else {
          setFavorites(prev => [...prev, pid]);
          showToast(`${name} saved to wishlist`, 'success');
      }
