export const BuyerDashboard: React.FC = () => {
  const { products, vendors, favorites, toggleFavorite, currentUser, addToCart, removeFromCart, cart, showToast, isDataLoading } = useApp();
  const navigate = useNavigate();
  const [selectedCat, setSelectedCat] = useState('All');
  const [sortType, setSortType] = useState<'nearby' | 'price' | 'rating'>('nearby');
  const [userLocation, setUserLocation] = useState<{lat: number, lng: number} | null>(null);

  useEffect(() => {
      if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(
              (pos) => setUserLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
              () => setUserLocation({ lat: 5.6506, lng: -0.1962 }),
              { enableHighAccuracy: true }
          );
      }
  }, []);

  const getDistanceFromLatLonInKm = (lat1: number, lon1: number, lat2: number, lon2: number) => {
      const R = 6371; 
      const dLat = (lat2 - lat1) * (Math.PI/180);
      const dLon = (lon2 - lon1) * (Math.PI/180);
      const a = Math.sin(dLat/2) * Math.sin(dLat/2) + Math.cos(lat1 * (Math.PI/180)) * Math.cos(lat2 * (Math.PI/180)) * Math.sin(dLon/2) * Math.sin(dLon/2); 
      return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a)));
  };

  const getCoordsForLocation = (locStr: string): {lat: number, lng: number} | null => {
      const clean = locStr.toLowerCase();
      if (INITIAL_LOCATION_CACHE[clean]) return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
      const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
      if (key) return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
      return null;
  };

  const categoryList = useMemo(() => {
      const standardNames = new Set(CATEGORIES.map(c => c.name));
      const customCategories = Array.from(new Set(products.map(p => p.category)))
        .filter(cat => cat && !standardNames.has(cat) && cat !== 'OTHER')
        .map(cat => ({
            id: `cat-custom-${cat.replace(/\s+/g, '-').toLowerCase()}`,
            name: cat,
            icon: 'tag',
            image: products.find(p => p.category === cat)?.images[0] || 'https://via.placeholder.com/150'
        }));

      return [{ id: 'cat-all', name: 'All', icon: 'layer-group', image: '' }, ...CATEGORIES, ...customCategories];
  }, [products]);

  const trendingProducts = useMemo(() => products.filter(p => p.isTrending && p.status === 'approved' && p.stock > 0), [products]);

  const sortedProducts = useMemo(() => {
      const approvedProducts = products.filter(p => p.status === 'approved');
      let filtered = selectedCat === 'All' ? approvedProducts : approvedProducts.filter(p => p.category === selectedCat);
      if (sortType === 'price') return [...filtered].sort((a, b) => a.price - b.price);
      if (sortType === 'rating') return [...filtered].sort((a, b) => (b.rating || 0) - (a.rating || 0));
      if (sortType === 'nearby' && userLocation) {
          return [...filtered].sort((a, b) => {
              const coordsA = getCoordsForLocation(a.location);
              const coordsB = getCoordsForLocation(b.location);
              return (coordsA ? getDistanceFromLatLonInKm(userLocation.lat, userLocation.lng, coordsA.lat, coordsA.lng) : 999) - (coordsB ? getDistanceFromLatLonInKm(userLocation.lat, userLocation.lng, coordsB.lat, coordsB.lng) : 999);
          });
      }
      return filtered;
  }, [products, selectedCat, sortType, userLocation]);

  return (
    <div className="flex flex-col space-y-6 animate-fade-in pb-10 bg-gray-50 dark:bg-darkBg min-h-screen overflow-x-hidden">

      {/* Dynamic Search Header */}
      <div className="bg-white/80 dark:bg-darkSurface/90 backdrop-blur-2xl pt-3 pb-4 px-5 sticky top-0 z-30 border-b border-gray-100 dark:border-gray-800 shadow-card">
        <div className="relative group" onClick={() => navigate('/buyer/search')}>
            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <i className="fa-solid fa-magnifying-glass text-gray-400 group-focus-within:text-primary transition-colors"></i>
            </div>
            <input readOnly placeholder="Search campus stores..." className="block w-full rounded-2xl border-2 border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-darkBg py-3.5 pl-12 pr-4 text-sm text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none cursor-pointer hover:border-primary/30 transition-all shadow-inner" />
        </div>
      </div>

      {/* Categories Scroller */}
      <div className="pl-5">
        <h3 className="font-display font-black text-gray-900 dark:text-white text-[10px] uppercase tracking-[0.2em] mb-4 opacity-50">Department Discovery</h3>
        <div className="flex gap-4 overflow-x-auto hide-scrollbar snap-x snap-mandatory pb-4 pr-5">
            {categoryList.map(cat => {
                const isSelected = selectedCat === cat.name;
                return (
                    <div key={cat.id} className="flex flex-col items-center justify-center gap-2 cursor-pointer min-w-[80px] snap-start" onClick={() => setSelectedCat(cat.name)}>
                        <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center transition-all overflow-hidden shadow-soft border-2 ${isSelected ? 'border-primary ring-4 ring-primary/20 scale-105' : 'border-transparent bg-white dark:bg-darkSurface'}`}>
                            {cat.image ? <img src={cat.image} alt={cat.name} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-gray-400"><i className={`fa-solid fa-${cat.icon} text-xl`}></i></div>}
                        </div>
                        <span className={`text-[10px] font-black text-center w-full uppercase tracking-tighter ${isSelected ? 'text-primary' : 'text-gray-400 dark:text-gray-500'}`}>{cat.name}</span>
                    </div>
                );
            })}
        </div>
      </div>

      {/* Spotlight Carousel */}
      {trendingProducts.length > 0 && (
          <div className="relative bg-indigo-50/30 dark:bg-primary/5 py-6 border-y border-indigo-100/50 dark:border-white/5">
            <div className="flex justify-between items-center mb-4 px-5">
                <h3 className="font-display font-black text-gray-900 dark:text-white text-[11px] uppercase tracking-[0.25em] flex items-center gap-2">
                    <i className="fa-solid fa-fire-flame-curved text-orange-500 text-sm animate-pulse"></i> Sponsored Drops
                </h3>
            </div>
            <div className="overflow-x-auto hide-scrollbar relative w-full group select-none">
                <div className="flex w-fit animate-scroll pause-on-hover py-2">
                    {[...trendingProducts, ...trendingProducts].map((p, idx) => (
                        <div key={`${p.id}-${idx}`} onClick={() => navigate(`/buyer/product/${p.id}`)} className="mx-2 w-[140px] md:w-[180px] bg-white dark:bg-darkSurface rounded-3xl p-1.5 shadow-soft border border-gray-100 dark:border-gray-800 active:scale-95 transition-all cursor-pointer flex-shrink-0">
                            <div className="aspect-[4/5] rounded-2xl overflow-hidden mb-2 bg-gray-50 dark:bg-gray-900 relative">
                                <img src={p.images[0]} className="w-full h-full object-cover" alt={p.title} />
                                <div className="absolute bottom-2 right-2 bg-black/90 backdrop-blur-md text-white text-[10px] px-2 py-1 rounded-xl font-black shadow-lg">₵{p.price}</div>
                            </div>
                            <div className="px-1.5 pb-1">
                                <h4 className="text-[11px] font-black text-gray-900 dark:text-white line-clamp-1 mb-0.5 leading-tight uppercase tracking-tighter">{p.title}</h4>
                                <span className="text-[8px] font-bold text-primary uppercase tracking-widest opacity-60">Verified Partner</span>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
          </div>
      )}

      {/* Feed */}
      <div className="px-5 pb-24">
         <div className="flex justify-between items-center mb-6">
            <h3 className="font-display font-black text-gray-900 dark:text-white text-lg uppercase tracking-tight">Recent Listings</h3>
            <div className="flex gap-2 p-1 bg-gray-100 dark:bg-darkSurface rounded-xl border border-gray-200 dark:border-gray-800 shadow-inner">
                {['nearby', 'price'].map(type => (
                    <button key={type} onClick={() => setSortType(type as any)} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${sortType === type ? 'bg-white dark:bg-primary text-primary dark:text-white shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}>{type}</button>
                ))}
            </div>
         </div>

         {isDataLoading ? (
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                 {[...Array(6)].map((_, i) => <ProductCardSkeleton key={i} />)}
            </div>
         ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                {sortedProducts.map(product => {
                    const isFav = favorites.includes(product.id);
                    const isInCart = cart.some(item => item.productId === product.id);
                    return (
                        <div key={product.id} className="bg-white dark:bg-darkSurface rounded-[2rem] overflow-hidden shadow-card hover:shadow-float border border-gray-100 dark:border-gray-800/50 transition-all duration-500 group flex flex-col h-full cursor-pointer relative" onClick={() => navigate(`/buyer/product/${product.id}`)}>
                            <div className="aspect-square w-full relative overflow-hidden bg-gray-50 dark:bg-gray-900">
                                <img src={product.images[0]} alt={product.title} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                                <div className="absolute top-3 left-3 glass px-3 py-1.5 rounded-2xl text-[9px] font-black shadow-sm flex items-center gap-1.5 z-20 text-gray-700 dark:text-white uppercase tracking-tighter">
                                     <i className="fa-solid fa-location-dot text-red-500"></i> {product.location}
                                </div>
                                <button className="absolute top-3 right-3 z-20 w-9 h-9 rounded-full glass border border-white/20 text-gray-400 hover:text-red-500 flex items-center justify-center transition-all shadow-sm active:scale-90" onClick={(e) => { e.stopPropagation(); toggleFavorite(product.id); }}>
                                    <i className={`${isFav ? 'fa-solid text-red-500 scale-110' : 'fa-regular'} fa-heart text-sm transition-all`}></i>
                                </button>
                                {product.stock === 0 && <div className="absolute inset-0 bg-black/60 backdrop-blur-[2px] flex items-center justify-center z-10"><span className="bg-black/80 text-white text-[10px] px-4 py-2 rounded-full font-black uppercase tracking-[0.2em] border border-white/20 shadow-2xl">Sold Out</span></div>}
                            </div>
                            <div className="p-5 flex flex-col justify-between flex-grow">
                                <div>
                                    <h3 className="text-sm text-gray-800 dark:text-white font-black leading-tight line-clamp-2 mb-2 group-hover:text-primary transition-colors">{product.title}</h3>
                                    <p className="text-[10px] text-gray-400 dark:text-gray-500 font-bold uppercase tracking-widest">{vendors.find(v => v.vendorId === product.vendorId)?.storeName}</p>
                                </div>
                                <div className="flex items-center justify-between mt-4">
                                    <span className="text-lg font-black text-gray-900 dark:text-white tracking-tighter">₵{product.price.toFixed(2)}</span>
                                    <button className={`w-10 h-10 rounded-2xl flex items-center justify-center text-white transition-all shadow-soft active:scale-90 ${isInCart ? 'bg-green-500 shadow-green-500/30' : 'bg-gray-900 dark:bg-white dark:text-black hover:bg-primary hover:text-white shadow-gray-900/20'}`} onClick={(e) => { e.stopPropagation(); if (product.stock > 0) isInCart ? removeFromCart(product.id) : addToCart(product); }}>
                                        <i className={`fa-solid ${isInCart ? 'fa-check' : 'fa-plus'} text-xs`}></i>
                                    </button>
                                </div>
                            </div>
                        </div>
                    )
                })}
            </div>
         )}
      </div>
    </div>
  );
};

import React, { createContext, useContext, useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { User, Product, Vendor, Order, CartItem, Courier, Role, OrderStatus, ToastMessage, Notification, NotificationPreferences } from './types';
import { supabase } from './supabaseClient';
import { INITIAL_LOCATION_CACHE } from './constants';

type ThemeMode = 'light' | 'dark' | 'system';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  couriers: Courier[];
  users: User[];
  notifications: Notification[];
  unreadCount: number;
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;
  theme: ThemeMode;
  isThemeSwitchingAllowed: boolean;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string, user?: any}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;
  updateTheme: (theme: ThemeMode) => void;
  toggleThemeSwitching: (allowed: boolean) => void;

  updateProfile: (data: Partial<User>) => Promise<{ success: boolean }>;
  submitContactMessage: (name: string, email: string, message: string) => Promise<{ success: boolean }>;
  requestPayout: (amount: number, method: string) => Promise<{ success: boolean }>;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerCourier: (data: Partial<Courier> & { phoneNumber?: string }, explicitUserId?: string) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  toggleTrendingStatus: (id: string, isTrending: boolean) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  markNotificationRead: (id: string) => Promise<void>;
  markAllNotificationsRead: () => Promise<void>;
  deleteNotification: (id: string) => Promise<void>;
  sendNotification: (payload: Partial<Notification>) => Promise<boolean>;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveCourier: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (INITIAL_LOCATION_CACHE[clean]) return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
    if (key) return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
    return { lat: 5.6506, lng: -0.1962 };
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [couriers, setCouriers] = useState<Courier[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [theme, setTheme] = useState<ThemeMode>(() => {
      try { return (localStorage.getItem('lynqed_theme_last') as ThemeMode) || 'system'; } catch { return 'system'; }
  });

  const [isThemeSwitchingAllowed, setIsThemeSwitchingAllowed] = useState<boolean>(() => {
      try { return localStorage.getItem('lynqed_sys_theme_allowed') !== 'false'; } catch { return true; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [connectionError, setConnectionError] = useState<boolean>(false);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const showToast = useCallback((message: string, type: 'success' | 'error' | 'info') => {
      setToast({ id: Date.now(), message, type });
  }, []);

  const hideToast = useCallback(() => setToast(null), []);

  const updateTheme = (newTheme: ThemeMode) => {
      setTheme(newTheme);
      safeSetItem('lynqed_theme_last', newTheme);
  };

  const toggleThemeSwitching = (allowed: boolean) => {
      setIsThemeSwitchingAllowed(allowed);
      safeSetItem('lynqed_sys_theme_allowed', String(allowed));
  };

  const resetPassword = async (email: string) => {
      const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/#/update-password` });
      return { success: !error, error: error?.message };
  };

  const updatePassword = async (newPassword: string) => {
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      return { success: !error, error: error?.message };
  };

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  const unreadCount = useMemo(() => notifications.filter(n => !n.isRead).length, [notifications]);

  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);

  useEffect(() => { 
      if (currentRole !== 'guest' && currentRole !== 'admin') safeSetItem('lynqed_role', currentRole); 
  }, [currentRole]);

  const fetchNotifications = useCallback(async () => {
      const { data: session } = await supabase.auth.getSession();
      const userId = session?.session?.user?.id;
      if (!userId) return;

      try {
          const { data, error } = await supabase
            .from('notifications')
            .select('*')
            .order('created_at', { ascending: false });

          if (!error && data) {
              setNotifications(data.map(n => ({
                  ...n, userId: n.user_id, targetRole: n.target_role,
                  targetScope: n.target_scope, relatedId: n.related_id,
                  isRead: n.is_read, createdAt: n.created_at
              })));
          }
      } catch (e) { console.warn("Notif Fetch Error", e); }
  }, []);

  useEffect(() => {
    initApp();
    try {
        const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
        const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, () => fetchData()).subscribe();
        const vendorSub = supabase.channel('public:vendors').on('postgres_changes', { event: '*', schema: 'public', table: 'vendors' }, () => fetchData()).subscribe();

        // REALTIME NOTIFICATIONS
        const notifSub = supabase.channel('public:notifications')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'notifications' }, () => fetchNotifications())
            .subscribe();

        return () => {
            supabase.removeChannel(productSub);
            supabase.removeChannel(orderSub);
            supabase.removeChannel(vendorSub);
            supabase.removeChannel(notifSub);
        };
    } catch (e) { console.error("Realtime subscription failed:", e); }
  }, [fetchNotifications]); 

  const initApp = async () => {
      try {
          await checkSession();
          await fetchData();
          await fetchNotifications();
          setConnectionError(false);
      } catch (e) { console.error("Initialization Failed:", e);
      } finally { setIsLoading(false); setIsDataLoading(false); }
  };

  const checkSession = async () => {
      try {
          const { data, error } = await supabase.auth.getSession();
          if (error) throw error;
          if (data.session?.user) await fetchUserProfile(data.session.user.id, data.session.user);
          else { setCurrentUser(null); setCurrentRole('guest'); }
      } catch (e) { console.error("Session check error:", e); } 
  };

  const fetchUserProfile = async (userId: string, sessionUser?: any): Promise<User | null> => {
      try {
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();
          if (error) throw error;
          if (data) {
              if (data.isBanned) throw new Error("Account Suspended");
              const user: User = { 
                  ...data, roles: data.roles || ['buyer'],
                  avatarUrl: data.avatar_url, phoneNumber: data.phone_number,
                  defaultLocation: data.address
              };
              setCurrentUser(user);
              const persistedRole = localStorage.getItem('lynqed_role') as Role;
              let finalRole: Role = (persistedRole && user.roles.includes(persistedRole)) ? persistedRole : (user.roles.includes('admin') ? 'admin' : (user.roles.includes('vendor') ? 'vendor' : 'buyer'));
              setCurrentRole(finalRole);
              return user;
          } else if (sessionUser) {
              await supabase.from('profiles').insert({ id: userId, email: sessionUser.email, name: sessionUser.user_metadata?.full_name || 'User', roles: ['buyer'] });
              return fetchUserProfile(userId);
          }
      } catch (e) { console.error("Profile fetch error", e); }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, select = '*', orderBy?: string) => {
             let query = supabase.from(table).select(select);
             if (orderBy) query = query.order(orderBy, { ascending: false });
             const { data } = await query;
             return data;
          };
          const [pData, vData, oData, cDataRaw] = await Promise.all([
              fetchSafely('products', '*', 'created_at'), fetchSafely('vendors'),
              fetchSafely('orders', '*', 'created_at'), fetchSafely('couriers')
          ]);
          if (pData) setProducts(pData.map((p: any) => ({ ...p, vendorId: p.vendor_id, contactPhone: p.contact_phone, isTrending: p.is_trending })));
          if (vData) setVendors(vData.map((v: any) => ({ ...v, vendorId: v.vendor_id, storeName: v.store_name, storeDescription: v.store_description, storeAvatarUrl: v.store_avatar_url, userId: v.user_id, isApproved: v.is_approved, contactPhone: v.contact_phone })));
          if (oData) setOrders(oData.map((o: any) => ({ ...o, vendorId: o.vendor_id, buyerId: o.buyer_id, courierId: o.courier_id, deliveryFee: o.delivery_fee, deliveryOption: o.delivery_option, createdAt: o.created_at, items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items, locationCoordinates: o.location_coordinates, pickupCoordinates: o.pickup_coordinates })));
          if (cDataRaw) {
              const { data: profiles } = await supabase.from('profiles').select('id, name, email');
              const profileMap = new Map(profiles?.map((p: any) => [p.id, p]));
              // Fix for line 268 (likely 238 internal): Cast profileMap.get result to any to access .name
              setCouriers(cDataRaw.map((d: any) => ({ ...d, userId: d.user_id, fullName: (profileMap.get(d.user_id) as any)?.name || 'Courier', vehicleType: d.vehicle_type, onlineStatus: d.online_status, status: d.status, verified: d.status === 'approved', payoutMethod: d.payout_method })));
          }
          if (localStorage.getItem('lynqed_role') === 'admin' || currentRole === 'admin') {
              const uData = await supabase.from('profiles').select('*');
              if (uData.data) setUsers(uData.data as any);
          }
      } catch (e) { console.error("Data Fetch Error:", e); } finally { setIsDataLoading(false); }
  };

  const sendNotification = async (payload: Partial<Notification>) => {
      try {
          const { error } = await supabase.from('notifications').insert({
              user_id: payload.userId, target_role: payload.targetRole,
              target_scope: payload.targetScope || 'individual', type: payload.type,
              title: payload.title, message: payload.message,
              related_id: payload.relatedId, priority: payload.priority || 'normal'
          });
          if (!error) { fetchNotifications(); return true; }
          return false;
      } catch (e) { return false; }
  };

  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) return { success: false, error: error.message };
      if (data.user) {
          const user = await fetchUserProfile(data.user.id, data.user);
          await Promise.all([fetchData(), fetchNotifications()]);
          return { success: true, role: currentUser?.roles[0] || 'buyer' };
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           await supabase.from('profiles').insert({ id: data.user.id, email, name: fullName, roles: role === 'buyer' ? ['buyer'] : ['buyer', role], phone_number: phoneNumber });
           return await login(email, password); 
      }
      return { success: false };
  };

  const logout = async () => { await supabase.auth.signOut(); setCurrentUser(null); setCurrentRole('guest'); setNotifications([]); setCart([]); };

  const switchRole = (role: Role) => { 
      if(currentUser?.roles.includes(role)) { setCurrentRole(role); safeSetItem('lynqed_role', role); showToast(`Switched to ${role.charAt(0).toUpperCase() + role.slice(1)} Mode`, 'info'); }
  };

  const markNotificationRead = async (id: string) => { await supabase.from('notifications').update({ is_read: true }).eq('id', id); fetchNotifications(); };
  const markAllNotificationsRead = async () => { if (!currentUser) return; await supabase.from('notifications').update({ is_read: true }).eq('user_id', currentUser.id).eq('is_read', false); fetchNotifications(); };
  const deleteNotification = async (id: string) => { await supabase.from('notifications').delete().eq('id', id); fetchNotifications(); };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });
      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);
              const { data, error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, vendor_id: vid, items, total: subtotal+fee, 
                  delivery_fee: fee, status: 'placed', delivery_option: option, 
                  pickup_coordinates: vendor ? resolveCoordinates(vendor.location) : undefined, 
                  location_coordinates: resolveCoordinates(currentUser.address || 'campus') 
              }).select().single();
              if (error) throw error;
              if (vendor) {
                  await sendNotification({ userId: vendor.userId, type: 'new_order', title: 'New Order Received!', message: `New order for ₵${(subtotal+fee).toFixed(2)}.`, relatedId: data.id, priority: 'high' });
              }
              for (const item of items) await supabase.from('products').update({ stock: Math.max(0, item.product.stock - item.quantity) }).eq('id', item.productId);
          }
          showToast("Order Placed!", "success"); clearCart(); fetchData();
      } catch (e) { showToast("Order failed", "error"); }
  };

  const updateOrderStatus = async (orderId: string, status: string) => { 
      const { error } = await supabase.from('orders').update({status}).eq('id', orderId); 
      if (!error) {
          const order = orders.find(o => o.id === orderId);
          if (order) {
              await sendNotification({ userId: order.buyerId, type: 'order_update', title: 'Order Update', message: `Order #${orderId.slice(-4)}: ${status.replace('_', ' ')}.`, relatedId: orderId });
              if (status === 'ready_for_pickup' && order.deliveryOption === 'delivery') {
                  await sendNotification({ targetScope: 'role', targetRole: 'courier', type: 'delivery', title: 'Job Available!', message: 'A package is ready for delivery.', relatedId: orderId, priority: 'high' });
              }
          }
          fetchData(); 
      }
  };

  const approveVendor = async (vid: string, s: boolean) => { 
      const { error } = await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid); 
      if (!error) {
          const vendor = vendors.find(v => v.vendorId === vid);
          if (vendor) await sendNotification({ userId: vendor.userId, type: 'approval', title: s ? 'Store Approved!' : 'Review Update', message: s ? 'Your store is live.' : 'Review status changed.', priority: 'high' });
          fetchData(); 
      }
  };

  const registerCourier = async (data: any, explicitUserId?: string): Promise<{ success: boolean }> => {
      const uid = explicitUserId || currentUser?.id;
      if(!uid) return { success: false };
      const { error } = await supabase.from('couriers').insert({ user_id: uid, status: 'pending', full_name: data.fullName, vehicle_type: data.vehicle_type });
      if(!error) { 
          await sendNotification({ targetScope: 'role', targetRole: 'admin', type: 'system', title: 'New Driver Applied', message: `${data.fullName} applied.` });
          fetchData(); return { success: true }; 
      }
      return { success: false };
  };

  const updateProfile = async (data: Partial<User>) => {
    if(!currentUser) return { success: false };
    const { error } = await supabase.from('profiles').update({ name: data.name, avatar_url: data.avatarUrl, phone_number: data.phoneNumber, address: data.address }).eq('id', currentUser.id);
    if(!error) { showToast("Profile updated", "success"); fetchUserProfile(currentUser.id); return { success: true }; }
    return { success: false };
  };

  const submitContactMessage = async (name: string, email: string, message: string) => { await supabase.from('contact_messages').insert({ name, email, message }); showToast("Sent!", "success"); return { success: true }; };
  const requestPayout = async (amount: number, method: string) => { if(!currentUser) return { success: false }; await supabase.from('payout_requests').insert({ user_id: currentUser.id, amount, method, status: 'pending' }); showToast("Requested", "success"); return { success: true }; };

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileName = `${Math.random().toString(36).substring(2)}_${Date.now()}.${file.name.split('.').pop()}`;
          const { error: upErr } = await supabase.storage.from('lynqed-assets').upload(`${folder}/${fileName}`, file);
          if (upErr) throw upErr;
          return supabase.storage.from('lynqed-assets').getPublicUrl(`${folder}/${fileName}`).data.publicUrl;
      } catch (e) { showToast('Upload failed', 'error'); return null; }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      const ex = vendors.find(v => v.userId === currentUser.id);
      const vid = ex?.vendorId || `v-${Date.now()}`;
      const { error } = await supabase.from('vendors').upsert({ vendor_id: vid, user_id: currentUser.id, store_name: data.storeName, store_description: data.storeDescription, location: data.location, contact_phone: data.contact_phone, store_avatar_url: data.storeAvatarUrl, is_approved: ex ? ex.isApproved : false, rating: ex ? ex.rating : 5.0 }, { onConflict: 'user_id' });
      if (!error) {
          if (!currentUser.roles.includes('vendor')) await supabase.from('profiles').update({ roles: [...new Set([...currentUser.roles, 'vendor' as Role, 'buyer' as Role])] }).eq('id', currentUser.id);
          if (!ex) await sendNotification({ targetScope: 'role', targetRole: 'admin', type: 'system', title: 'New Store Request', message: `${data.storeName} applied.` });
          fetchData(); return { success: true };
      }
      return { success: false };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) return false;
      const v = vendors.find(v => v.userId === currentUser.id);
      if(!v) return false;
      const { error } = await supabase.from('products').insert({ vendor_id: v.vendorId, title: prod.title, description: prod.description, price: prod.price, category: prod.category, images: prod.images, stock: prod.stock, status: 'pending', location: prod.location, contact_phone: prod.contact_phone });
      if (!error) { 
          showToast("Submitted", "success"); 
          await sendNotification({ targetScope: 'role', targetRole: 'admin', type: 'approval', title: 'Item for Review', message: `New item from ${v.storeName}.` });
          fetchData(); return true; 
      }
      return false;
  };

  const updateProduct = async (id: string, data: any) => { await supabase.from('products').update({ ...data, contact_phone: data.contactPhone }).eq('id', id); fetchData(); };
  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };
  const updateProductStatus = async (id: string, status: string) => { 
      await supabase.from('products').update({status}).eq('id', id); 
      const prod = products.find(p => p.id === id);
      const v = vendors.find(v => v.vendorId === prod?.vendorId);
      if (v) await sendNotification({ userId: v.userId, type: 'approval', title: 'Item Update', message: `"${prod?.title}" is ${status}.` });
      fetchData(); 
  };

  const toggleTrendingStatus = async (id: string, isTrending: boolean) => { await supabase.from('products').update({ is_trending: isTrending }).eq('id', id); fetchData(); };
  const addToCart = useCallback((p: Product, q = 1) => { setCart(prev => { const ex = prev.find(i => i.productId === p.id); return ex ? prev.map(i => i.productId === p.id ? { ...i, quantity: i.quantity + q } : i) : [...prev, { productId: p.id, quantity: q, product: p }]; }); showToast(`Added ${p.title}`, "success"); }, [showToast]);
  const removeFromCart = useCallback((pid: string) => { setCart(prev => prev.filter(i => i.productId !== pid)); showToast("Removed", "info"); }, [showToast]);
  const updateCartQuantity = useCallback((pid: string, qty: number) => { if(qty <= 0) removeFromCart(pid); else { setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i)); } }, [removeFromCart]);
  const clearCart = useCallback(() => { setCart([]); showToast("Cleared", "info"); }, [showToast]);
  const toggleFavorite = useCallback((pid: string) => { const isRem = favorites.includes(pid); setFavorites(prev => isRem ? prev.filter(i => i !== pid) : [...prev, pid]); showToast(isRem ? 'Removed' : 'Saved', isRem ? 'info' : 'success'); }, [favorites, showToast]);
  const assignDelivery = async (oid: string) => { if (!currentUser) return; await supabase.from('orders').update({ courier_id: currentUser.id, status: 'courier_assigned' }).eq('id', oid); const order = orders.find(o => o.id === oid); if (order) await sendNotification({ userId: order.buyerId, type: 'delivery', title: 'Driver Assigned!', message: `A courier is on the way.`, relatedId: oid }); fetchData(); };
  const toggleDriverStatus = async (isOn: boolean) => { if(!currentUser) return; const c = couriers.find(d => d.userId === currentUser.id); if(c) { await supabase.from('couriers').update({ online_status: isOn }).eq('id', c.id); fetchData(); } };
  const updateDriverLocation = async (lat: number, lng: number) => { if(!currentUser) return; const c = couriers.find(d => d.userId === currentUser.id); if(c) supabase.from('couriers').update({ current_lat: lat, current_lng: lng }).eq('id', c.id).then(); };
  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };
  const approveCourier = async (id: string, userId: string, status: string) => { await supabase.from('couriers').update({status}).eq('id', id); if (status === 'approved') { const profile = users.find(u => u.id === userId); if (profile) await supabase.from('profiles').update({ roles: [...new Set([...profile.roles, 'courier' as Role, 'buyer' as Role])] }).eq('id', userId); await sendNotification({ userId, type: 'approval', title: 'Driver Verified!', message: 'You are now live.' }); } fetchData(); };
  const requestNotificationPermission = async () => true;
  const refreshData = async () => { setIsDataLoading(true); await Promise.all([fetchData(), fetchNotifications()]); setIsDataLoading(false); };

  const contextValue = useMemo(() => ({
    currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, unreadCount, isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed,
    login, signup, logout, resetPassword, updatePassword, switchRole, updateTheme, toggleThemeSwitching,
    updateProfile, submitContactMessage, requestPayout, uploadFile, registerCourier, registerVendor, refreshData,
    addProduct, updateProduct, updateProductStatus, toggleTrendingStatus, deleteProduct, addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
    markNotificationRead, markAllNotificationsRead, deleteNotification, sendNotification, banUser, deleteUser, approveVendor, approveCourier, toggleDriverStatus, updateDriverLocation, showToast, hideToast, requestNotificationPermission
  }), [currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, unreadCount, isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed, addToCart, removeFromCart, updateCartQuantity, fetchNotifications]);

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) throw new Error('useApp must be used within an AppProvider');
  return context;
};

