import React, { useState, useEffect, useRef } from 'react';
import { useApp } from '../context';
import { Button, Card, Input, Badge, Avatar, Spinner } from '../components/UI';
import { useNavigate, Link } from 'react-router-dom';
import { Role, TransportType } from '../types';

// --- Review Submission Modal ---
const ReviewModal: React.FC<{ 
    productId: string; 
    vendorId: string; 
    onClose: () => void;
}> = ({ productId, vendorId, onClose }) => {
    const { submitReview, currentUser } = useApp();
    const [rating, setRating] = useState(5);
    const [comment, setComment] = useState('');
    const [submitting, setSubmitting] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!currentUser) return;
        setSubmitting(true);
        const success = await submitReview({
            productId,
            vendorId,
            userId: currentUser.id,
            rating,
            comment,
            images: []
        });
        if (success) onClose();
        setSubmitting(false);
    };

    return (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in">
            <Card className="p-6 w-full max-w-md rounded-t-[2.5rem] sm:rounded-3xl animate-slide-up bg-white dark:bg-darkSurface">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-display font-black dark:text-white uppercase tracking-tight">Rate Your Purchase</h3>
                    <button onClick={onClose} className="w-8 h-8 rounded-full bg-gray-50 dark:bg-gray-800 flex items-center justify-center">
                        <i className="fa-solid fa-xmark text-gray-400"></i>
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="flex justify-center gap-3 py-4">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button
                                key={star}
                                type="button"
                                onClick={() => setRating(star)}
                                className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl transition-all ${star <= rating ? 'bg-yellow-400 text-white shadow-lg shadow-yellow-200' : 'bg-gray-100 dark:bg-gray-800 text-gray-300'}`}
                            >
                                <i className="fa-solid fa-star"></i>
                            </button>
                        ))}
                    </div>

                    <div>
                        <label className="block text-[10px] font-black uppercase text-gray-400 mb-2 ml-1">Comment</label>
                        <textarea
                            className="w-full rounded-2xl bg-gray-50 dark:bg-gray-800 p-4 text-sm h-32 outline-none focus:ring-2 focus:ring-primary/20 dark:text-white"
                            placeholder="How was the product? Fast delivery? Quality?"
                            value={comment}
                            onChange={e => setComment(e.target.value)}
                            required
                        />
                    </div>

                    <Button fullWidth size="lg" type="submit" disabled={submitting}>
                        {submitting ? 'Submitting...' : 'Post Review'}
                    </Button>
                </form>
            </Card>
        </div>
    );
};

// --- Order Progress Tracker ---
const OrderProgress: React.FC<{ order: any }> = ({ order }) => {
    const steps = order.deliveryOption === 'delivery' 
        ? ['placed', 'received', 'preparing', 'courier_assigned', 'delivering', 'delivered']
        : ['placed', 'received', 'preparing', 'ready_for_pickup', 'delivered'];

    const currentIndex = steps.indexOf(order.status);

    return (
        <div className="py-4">
            <div className="flex justify-between relative">
                <div className="absolute top-1/2 left-0 right-0 h-0.5 bg-gray-100 dark:bg-gray-800 -translate-y-1/2 z-0"></div>
                <div 
                    className="absolute top-1/2 left-0 h-0.5 bg-primary -translate-y-1/2 z-0 transition-all duration-500"
                    style={{ width: `${Math.max(0, (currentIndex / (steps.length - 1)) * 100)}%` }}
                ></div>
                {steps.map((step, idx) => (
                    <div key={step} className="relative z-10 flex flex-col items-center">
                        <div className={`w-3 h-3 rounded-full border-2 transition-colors duration-300 ${idx <= currentIndex ? 'bg-primary border-primary' : 'bg-white dark:bg-darkSurface border-gray-200 dark:border-gray-700'}`}></div>
                    </div>
                ))}
            </div>
            <div className="flex justify-between mt-2">
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">Start</span>
                <span className="text-[10px] font-bold text-primary uppercase tracking-tighter">{order.status.replace('_', ' ')}</span>
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">Done</span>
            </div>
        </div>
    );
};

