                    <button onClick={handleShare} className="w-9 h-9 rounded-full flex items-center justify-center text-gray-400 hover:text-primary transition-all"><i className="fa-solid fa-share-nodes"></i></button>
                </div>
            </div>

            <div className="max-w-7xl mx-auto p-4 md:p-8">
                <div className="bg-white dark:bg-darkSurface rounded-[2.5rem] shadow-soft overflow-hidden grid grid-cols-1 lg:grid-cols-2 gap-0">
