                                </div>
                                <i className="fa-solid fa-arrow-right text-gray-300"></i>
                            </div>
                        </div>
                    </div>
                </div>

                {/* TEMU STYLE REVIEWS SECTION */}
                <div className="mt-16 bg-white dark:bg-darkSurface rounded-[2.5rem] p-8 shadow-sm border border-gray-100 dark:border-gray-800">
