                                    const perc = productReviews.length > 0 ? (count / productReviews.length) * 100 : 0;
                                    return (
                                        <div key={stars} className="flex items-center gap-3">
                                            <span className="text-[10px] font-bold text-gray-500 w-4">{stars}</span>
                                            <div className="flex-1 h-1.5 bg-gray-100 dark:bg-gray-800 rounded-full overflow-hidden">
                                                <div className="h-full bg-yellow-400" style={{ width: `${perc}%` }}></div>
                                            </div>
                                            <span className="text-[10px] font-bold text-gray-400 w-4">{count}</span>
                                        </div>
                                    )
                                })}
