// --- Shared Review Modal Component ---
const ReviewModal: React.FC<{ 
    productId: string; 
    vendorId: string; 
    onClose: () => void;
}> = ({ productId, vendorId, onClose }) => {
    const { submitReview, currentUser } = useApp();
    const [rating, setRating] = useState(5);
    const [comment, setComment] = useState('');
    const [submitting, setSubmitting] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!currentUser) return;
        setSubmitting(true);
        const success = await submitReview({
            productId,
            vendorId,
            userId: currentUser.id,
            rating,
            comment,
            images: []
        });
        if (success) onClose();
        setSubmitting(false);
    };

    return (
        <div className="fixed inset-0 z-[100] bg-black/70 backdrop-blur-md flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in">
            <Card className="p-8 w-full max-w-lg rounded-t-[3rem] sm:rounded-[2.5rem] animate-slide-up bg-white dark:bg-darkSurface shadow-2xl border-none">
                <div className="flex justify-between items-center mb-8">
                    <div>
                        <h3 className="text-2xl font-display font-black dark:text-white uppercase tracking-tight">Product Review</h3>
                        <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mt-1">Share your campus experience</p>
                    </div>
                    <button onClick={onClose} className="w-10 h-10 rounded-full bg-gray-50 dark:bg-gray-800 flex items-center justify-center transition-transform active:scale-90">
                        <i className="fa-solid fa-xmark text-gray-400"></i>
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="space-y-8">
                    <div className="text-center">
                        <p className="text-[10px] font-black uppercase text-gray-400 mb-4 tracking-widest">Tap stars to rate</p>
                        <div className="flex justify-center gap-4">
                            {[1, 2, 3, 4, 5].map((star) => (
                                <button
                                    key={star}
                                    type="button"
                                    onClick={() => setRating(star)}
                                    className={`w-14 h-14 rounded-2xl flex items-center justify-center text-2xl transition-all duration-300 ${star <= rating ? 'bg-yellow-400 text-white shadow-lg shadow-yellow-400/30 scale-110' : 'bg-gray-100 dark:bg-gray-800 text-gray-300 hover:text-yellow-200'}`}
                                >
                                    <i className="fa-solid fa-star"></i>
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="block text-[10px] font-black uppercase text-gray-400 ml-1 tracking-widest">Your Comments</label>
                        <textarea
                            className="w-full rounded-[1.5rem] bg-gray-50 dark:bg-gray-900 p-5 text-sm h-36 outline-none border-2 border-transparent focus:border-primary/20 dark:text-white transition-all placeholder:text-gray-300"
                            placeholder="How was the quality? Was the vendor helpful? Delivery speed?"
                            value={comment}
                            onChange={e => setComment(e.target.value)}
                            required
                        />
                    </div>

                    <Button fullWidth size="lg" type="submit" disabled={submitting} className="h-16 text-lg shadow-glow">
                        {submitting ? <i className="fa-solid fa-circle-notch fa-spin"></i> : 'Post Verified Review'}
                    </Button>
                </form>
            </Card>
        </div>
    );
};

export const StorePage: React.FC = () => {
