export const ProductDetail: React.FC = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { products, addToCart, cart, updateCartQuantity, vendors, favorites, toggleFavorite, showToast, reviews, orders, currentUser } = useApp();
    const [selectedImageIndex, setSelectedImageIndex] = useState(0);
    const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);
    const scrollContainerRef = useRef<HTMLDivElement>(null);

    const product = products.find(p => p.id === id);
    const vendor = vendors.find(v => v.vendorId === product?.vendorId);

    // Check if current user has a delivered order for this product
    const hasDeliveredOrder = useMemo(() => {
        if (!currentUser) return false;
        return orders.some(o => 
            o.buyerId === currentUser.id && 
            o.status === 'delivered' && 
            o.items.some(i => i.productId === id)
        );
    }, [orders, currentUser, id]);

    // Check if user already reviewed this product
    const hasAlreadyReviewed = useMemo(() => {
        if (!currentUser) return false;
        return reviews.some(r => r.productId === id && r.userId === currentUser.id);
    }, [reviews, currentUser, id]);

    // Filtering real-time reviews for this product
    const productReviews = useMemo(() => reviews.filter(r => r.productId === id), [reviews, id]);

    const ratingStats = useMemo(() => {
        if (productReviews.length === 0) return { avg: 5, count: 0 };
        const sum = productReviews.reduce((acc, curr) => acc + curr.rating, 0);
        return { avg: (sum / productReviews.length).toFixed(1), count: productReviews.length };
    }, [productReviews]);

    const relatedProducts = products
        .filter(p => p.category === product?.category && p.id !== product?.id && p.status === 'approved')
        .slice(0, 10);

    const [quantity, setQuantity] = useState(1);

    if (!product) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const cartItem = cart.find(i => i.productId === product.id);
    const isInCart = !!cartItem;
    const isFav = favorites.includes(product.id);

    useEffect(() => {
        if (cartItem) setQuantity(cartItem.quantity);
    }, [cartItem]);

    const handleQuantity = (delta: number) => {
        setQuantity(prev => Math.max(1, Math.min(product.stock, prev + delta)));
    };

    const handleBuyNow = () => {
        if (isInCart) updateCartQuantity(product.id, quantity);
        else addToCart(product, quantity);
        navigate('/buyer/checkout');
    };

    const handleShare = async () => {
        const shareUrl = window.location.href;
        try {
            if (navigator.share) await navigator.share({ title: product.title, url: shareUrl });
            else throw new Error();
        } catch (err) {
            await navigator.clipboard.writeText(shareUrl);
            showToast("Product link copied!", "success");
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-20 animate-fade-in">
            <div className="bg-white/80 dark:bg-darkSurface/80 backdrop-blur-md border-b border-gray-200 dark:border-gray-800 sticky top-0 z-30 px-4 py-3 flex items-center gap-3">
                <button onClick={() => navigate(-1)} className="w-9 h-9 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-600 dark:text-gray-300"><i className="fa-solid fa-arrow-left"></i></button>
                <div className="text-xs text-gray-500 dark:text-gray-400 flex items-center gap-2 overflow-hidden whitespace-nowrap">
                    <Link to="/buyer/dashboard" className="hover:text-primary transition-colors">Home</Link>
                    <i className="fa-solid fa-chevron-right text-[8px] opacity-40"></i>
                    <span className="truncate">{product.category}</span>
                </div>
                <div className="ml-auto flex gap-2">
                    <button onClick={() => toggleFavorite(product.id)} className={`w-9 h-9 rounded-full flex items-center justify-center transition-all ${isFav ? 'bg-red-50 text-red-500' : 'text-gray-400 hover:text-red-500'}`}><i className={`${isFav ? 'fa-solid' : 'fa-regular'} fa-heart`}></i></button>
                    <button onClick={handleShare} className="w-9 h-9 rounded-full flex items-center justify-center text-gray-400 hover:text-primary transition-all"><i className="fa-solid fa-share-nodes"></i></button>
                </div>
            </div>

            <div className="max-w-7xl mx-auto p-4 md:p-8">
                <div className="bg-white dark:bg-darkSurface rounded-[2.5rem] shadow-soft overflow-hidden grid grid-cols-1 lg:grid-cols-2 gap-0">
                    <div className="p-4 md:p-10 flex flex-col gap-6">
                        <div className="aspect-square w-full bg-gray-50 dark:bg-gray-900 rounded-[2rem] overflow-hidden border border-gray-100 dark:border-gray-800 relative">
                            <div ref={scrollContainerRef} className="w-full h-full flex overflow-x-auto snap-x snap-mandatory hide-scrollbar" onScroll={e => setSelectedImageIndex(Math.round(e.currentTarget.scrollLeft / e.currentTarget.clientWidth))}>
                                {product.images.map((img, idx) => (
                                    <div key={idx} className="w-full h-full flex-shrink-0 snap-center flex items-center justify-center p-6">
                                        <img src={img} alt={`${product.title} ${idx + 1}`} className="max-w-full max-h-full object-contain" />
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>

                    <div className="p-6 md:p-10 lg:border-l border-gray-100 dark:border-gray-800 flex flex-col">
                        <div className="mb-6">
                            <Badge color="violet" className="mb-3">{product.category}</Badge>
                            <h1 className="text-3xl md:text-4xl font-display font-black text-gray-900 dark:text-white leading-tight tracking-tight">{product.title}</h1>
                            <div className="flex items-center gap-3 mt-4">
                                <div className="flex text-yellow-400 text-sm">
                                    {[1,2,3,4,5].map(i => <i key={i} className={`fa-solid fa-star ${i <= Number(ratingStats.avg) ? '' : 'text-gray-200 dark:text-gray-700'}`}></i>)}
                                </div>
                                <span className="text-xs text-gray-500 dark:text-gray-400 font-bold uppercase tracking-tighter">{ratingStats.count} Verified Reviews</span>
                            </div>
                        </div>

                        <div className="bg-gray-50 dark:bg-gray-900/50 rounded-3xl p-6 mb-8">
                            <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mb-1">Current Price</p>
                            <div className="flex items-baseline gap-2">
                                <span className="text-4xl font-black text-gray-900 dark:text-white">₵{product.price.toFixed(2)}</span>
                            </div>
                        </div>

                        <div className="mb-8">
                            <h3 className="font-display font-black text-gray-900 dark:text-white text-sm uppercase tracking-widest mb-3">Description</h3>
                            <p className="text-gray-600 dark:text-gray-400 leading-relaxed text-base">{product.description}</p>
                        </div>

                        <div className="mt-auto space-y-6">
                            <div className="flex flex-wrap gap-4">
                                <div className="flex items-center bg-gray-100 dark:bg-gray-800 rounded-2xl h-14 w-36 px-2">
                                    <button onClick={() => handleQuantity(-1)} disabled={quantity <= 1} className="w-10 h-10 flex items-center justify-center text-gray-500 hover:text-primary disabled:opacity-30"><i className="fa-solid fa-minus"></i></button>
                                    <span className="flex-1 text-center font-black text-lg dark:text-white">{quantity}</span>
                                    <button onClick={() => handleQuantity(1)} disabled={quantity >= product.stock} className="w-10 h-10 flex items-center justify-center text-gray-500 hover:text-primary disabled:opacity-30"><i className="fa-solid fa-plus"></i></button>
                                </div>
                                <button onClick={handleBuyNow} disabled={product.stock === 0} className="flex-1 min-w-[180px] h-14 rounded-2xl font-black text-white shadow-xl flex items-center justify-center gap-3 transition-all active:scale-95 bg-gradient-to-r from-primary to-primaryDark hover:shadow-glow">
                                    <i className="fa-solid fa-bolt-lightning"></i> Checkout Now
                                </button>
                            </div>
                            <div className="p-4 bg-white dark:bg-gray-900 border border-gray-100 dark:border-gray-800 rounded-3xl flex items-center gap-4 cursor-pointer hover:border-primary/50 transition-all shadow-sm" onClick={() => navigate(`/store/${vendor?.vendorId}`)}>
                                <Avatar src={vendor?.storeAvatarUrl} name={vendor?.storeName || 'Vendor'} size="lg" className="rounded-2xl border-2 border-primary/10" />
                                <div className="flex-1">
                                    <p className="text-[10px] font-black text-primary uppercase tracking-[0.2em]">Verified Seller</p>
                                    <p className="text-lg font-display font-black text-gray-900 dark:text-white leading-tight">{vendor?.storeName}</p>
                                </div>
                                <i className="fa-solid fa-arrow-right text-gray-300"></i>
                            </div>
                        </div>
                    </div>
                </div>

                {/* TEMU STYLE REVIEWS SECTION */}
                <div className="mt-16 bg-white dark:bg-darkSurface rounded-[2.5rem] p-8 md:p-12 shadow-sm border border-gray-100 dark:border-gray-800 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-primary/5 rounded-full -mr-32 -mt-32 blur-3xl"></div>

                    <div className="flex flex-col lg:flex-row lg:items-center justify-between mb-12 gap-8 relative z-10">
                        <div>
                            <h2 className="text-3xl font-display font-black text-gray-900 dark:text-white mb-2">Customer Feedback</h2>
                            <div className="flex items-center gap-2">
                                <Badge color="green" className="px-2 py-0.5"><i className="fa-solid fa-shield-check mr-1"></i> Verified Purchases</Badge>
                                <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">{ratingStats.count} Total reviews</p>
                            </div>
                        </div>

                        <div className="flex flex-wrap items-center gap-6 md:gap-12">
                            <div className="text-center">
                                <p className="text-5xl font-display font-black text-gray-900 dark:text-white">{ratingStats.avg}</p>
                                <div className="flex text-yellow-400 text-xs justify-center my-1.5">
                                    {[1,2,3,4,5].map(i => <i key={i} className={`fa-solid fa-star ${i <= Number(ratingStats.avg) ? '' : 'text-gray-200 dark:text-gray-700'}`}></i>)}
                                </div>
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Rating Score</p>
                            </div>

                            <div className="h-16 w-px bg-gray-100 dark:bg-gray-800 hidden md:block"></div>

                            <div className="flex-1 min-w-[220px] space-y-1.5">
                                {[5,4,3,2,1].map(stars => {
                                    const count = productReviews.filter(r => r.rating === stars).length;
                                    const perc = productReviews.length > 0 ? (count / productReviews.length) * 100 : 0;
                                    return (
                                        <div key={stars} className="flex items-center gap-4">
                                            <span className="text-[10px] font-black text-gray-400 w-3">{stars}</span>
                                            <div className="flex-1 h-2 bg-gray-100 dark:bg-gray-800 rounded-full overflow-hidden">
                                                <div className="h-full bg-yellow-400 shadow-[0_0_8px_rgba(250,204,21,0.5)]" style={{ width: `${perc}%` }}></div>
                                            </div>
                                            <span className="text-[10px] font-bold text-gray-400 w-6 text-right">{count}</span>
                                        </div>
                                    )
                                })}
                            </div>

                            {/* DYNAMIC ACTION BUTTON */}
                            <div className="w-full md:w-auto">
                                {hasDeliveredOrder ? (
                                    hasAlreadyReviewed ? (
                                        <div className="bg-emerald-50 dark:bg-emerald-900/20 px-6 py-4 rounded-2xl border border-emerald-100 dark:border-emerald-800 text-center">
                                            <i className="fa-solid fa-circle-check text-emerald-500 mb-1 block"></i>
                                            <p className="text-[10px] font-black text-emerald-600 dark:text-emerald-400 uppercase tracking-widest">Feedback Recorded</p>
                                        </div>
                                    ) : (
                                        <Button 
                                            variant="primary" 
                                            className="h-16 px-10 shadow-glow animate-pulse" 
                                            onClick={() => setIsReviewModalOpen(true)}
                                            icon="pen-to-square"
                                        >
                                            Rate Product
                                        </Button>
                                    )
                                ) : (
                                    <div className="bg-gray-50 dark:bg-gray-800/50 p-4 rounded-2xl border border-gray-100 dark:border-gray-800 max-w-[200px]">
                                        <p className="text-[9px] font-black text-gray-400 dark:text-gray-500 leading-relaxed uppercase tracking-tighter">
                                            <i className="fa-solid fa-lock mr-1.5 text-[8px]"></i> 
                                            Review access granted after purchase completion.
                                        </p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>

                    <div className="space-y-10 relative z-10">
                        {productReviews.length === 0 ? (
                            <div className="text-center py-16 border-2 border-dashed border-gray-100 dark:border-gray-800 rounded-[2.5rem] bg-gray-50/30 dark:bg-black/10">
                                <div className="w-20 h-20 bg-white dark:bg-darkSurface rounded-full flex items-center justify-center mx-auto mb-6 shadow-sm">
                                    <i className="fa-solid fa-comments text-gray-200 dark:text-gray-700 text-3xl"></i>
                                </div>
                                <h4 className="text-gray-900 dark:text-white font-bold mb-1">No community reviews yet</h4>
                                <p className="text-gray-400 text-xs font-medium">Be the pioneer and share your thoughts after buying!</p>
                            </div>
                        ) : (
                            productReviews.map((review, idx) => (
                                <div key={review.id} className="animate-fade-in group">
                                    <div className="flex justify-between items-start mb-4">
                                        <div className="flex items-center gap-4">
                                            <Avatar src={review.user?.avatarUrl} name={review.user?.name || 'User'} size="md" className="border-2 border-white dark:border-gray-800 shadow-sm" />
                                            <div>
                                                <p className="text-sm font-black text-gray-900 dark:text-white leading-none mb-2">{review.user?.name}</p>
                                                <div className="flex items-center gap-3">
                                                    <div className="flex text-yellow-400 text-[10px]">
                                                        {[1,2,3,4,5].map(i => <i key={i} className={`fa-solid fa-star ${i <= review.rating ? '' : 'text-gray-100 dark:text-gray-800'}`}></i>)}
                                                    </div>
                                                    <div className="h-3 w-px bg-gray-200 dark:bg-gray-700"></div>
                                                    <span className="text-[8px] font-black text-primary dark:text-primaryLight uppercase tracking-widest flex items-center gap-1">
                                                        <i className="fa-solid fa-circle-check text-[10px]"></i> Verified
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                        <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest bg-gray-50 dark:bg-gray-800 px-3 py-1 rounded-full">{new Date(review.createdAt).toLocaleDateString()}</span>
                                    </div>
                                    <div className="pl-14">
                                        <p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed font-medium bg-gray-50/50 dark:bg-white/5 p-5 rounded-2xl border border-gray-100 dark:border-gray-800 group-hover:border-primary/10 transition-all">
                                            {review.comment}
                                        </p>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>

                {relatedProducts.length > 0 && (
                    <div className="mt-20">
                        <div className="flex items-center gap-4 mb-10">
                            <h3 className="font-display font-black text-3xl text-gray-900 dark:text-white tracking-tight">Recommended Deals</h3>
                            <div className="h-px flex-1 bg-gray-100 dark:bg-gray-800"></div>
                        </div>
                        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-6">
                            {relatedProducts.map(rp => (
                                <div key={rp.id} onClick={() => { navigate(`/buyer/product/${rp.id}`); window.scrollTo({ top: 0, behavior: 'smooth' }); }} className="bg-white dark:bg-darkSurface rounded-[2.5rem] border border-gray-100 dark:border-gray-800 p-4 shadow-card hover:shadow-xl transition-all cursor-pointer group flex flex-col h-full">
                                    <div className="aspect-square bg-gray-50 dark:bg-gray-900 rounded-[1.8rem] overflow-hidden mb-5 relative">
                                        <img src={rp.images[0]} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                                        <div className="absolute bottom-3 right-3 px-4 py-1.5 bg-black/90 dark:bg-white/90 dark:text-black text-white backdrop-blur-md rounded-2xl text-[10px] font-black shadow-xl">₵{rp.price}</div>
                                    </div>
                                    <h4 className="font-bold text-sm text-gray-900 dark:text-white line-clamp-2 px-1 mb-3 leading-snug group-hover:text-primary transition-colors">{rp.title}</h4>
                                    <div className="mt-auto px-1 flex justify-between items-center opacity-60 group-hover:opacity-100 transition-opacity">
                                        <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">{rp.category}</span>
                                        <i className="fa-solid fa-arrow-right text-[10px] text-primary translate-x-[-4px] group-hover:translate-x-0 transition-transform"></i>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>

            {isReviewModalOpen && product && (
                <ReviewModal 
                    productId={product.id} 
                    vendorId={product.vendorId} 
                    onClose={() => setIsReviewModalOpen(false)} 
                />
            )}
        </div>
    );
};

