const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [couriers, setCouriers] = useState<Courier[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [reviews, setReviews] = useState<Review[]>([]);

  // Advanced State
  const [rewardWallet, setRewardWallet] = useState<RewardWallet | null>(null);
  const [flashSales, setFlashSales] = useState<FlashSale[]>([]);
  const [activeGroupBuys, setActiveGroupBuys] = useState<GroupBuy[]>([]);

  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [theme, setTheme] = useState<ThemeMode>(() => {
      try { return (localStorage.getItem('lynqed_theme_last') as ThemeMode) || 'system'; } catch { return 'system'; }
  });

  const [isThemeSwitchingAllowed, setIsThemeSwitchingAllowed] = useState<boolean>(() => {
      try { return localStorage.getItem('lynqed_sys_theme_allowed') !== 'false'; } catch { return true; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [connectionError, setConnectionError] = useState<boolean>(false);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const showToast = useCallback((message: string, type: 'success' | 'error' | 'info') => {
      setToast({ id: Date.now(), message, type });
  }, []);

  const hideToast = useCallback(() => setToast(null), []);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  const unreadCount = useMemo(() => notifications.filter(n => !n.isRead).length, [notifications]);

  useEffect(() => { localStorage.setItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, select = '*', orderBy?: string) => {
             let query = supabase.from(table).select(select);
             if (orderBy) query = query.order(orderBy, { ascending: false });
             const { data } = await query;
             return data;
          };

          const [pData, vData, oData, cDataRaw, fsData, gbData] = await Promise.all([
              fetchSafely('products', '*', 'created_at'), 
              fetchSafely('vendors'),
              fetchSafely('orders', '*', 'created_at'), 
              fetchSafely('couriers'),
              fetchSafely('flash_sales'),
              fetchSafely('group_buys')
          ]);

          if (fsData) setFlashSales(fsData as any);
          if (gbData) setActiveGroupBuys(gbData as any);

          if (pData) {
              setProducts(pData.map((p: any) => {
                  const sale = fsData?.find((s: any) => s.product_id === p.id && s.is_active);
                  const groups = gbData?.find((g: any) => g.product_id === p.id && g.status === 'open');
                  return {
                      ...p,
                      vendorId: p.vendor_id,
                      contactPhone: p.contact_phone,
                      isTrending: p.is_trending,
                      flashSale: sale ? { ...sale, productId: sale.product_id, discountPrice: sale.discount_price, startTime: sale.start_time, endTime: sale.end_time } : undefined,
                      activeGroupBuy: groups ? { ...groups, productId: groups.product_id, creatorId: groups.creator_id, groupPrice: groups.group_price, expiryTime: groups.expiry_time } : undefined
                  };
              }));
          }

          if (vData) setVendors(vData.map((v: any) => ({ ...v, vendorId: v.vendor_id, storeName: v.store_name, storeDescription: v.store_description, storeAvatarUrl: v.store_avatar_url, userId: v.user_id, isApproved: v.is_approved, contactPhone: v.contact_phone })));
          if (oData) setOrders(oData.map((o: any) => ({ ...o, vendorId: o.vendor_id, buyerId: o.buyer_id, courierId: o.courier_id, deliveryFee: o.delivery_fee, deliveryOption: o.delivery_option, createdAt: o.created_at, items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items, locationCoordinates: o.location_coordinates, pickupCoordinates: o.pickup_coordinates })));

          if (currentUser) {
              const { data: wallet } = await supabase.from('rewards_wallet').select('*').eq('user_id', currentUser.id).maybeSingle();
              if (wallet) setRewardWallet({ userId: wallet.user_id, balance: wallet.balance, lifetimePoints: wallet.lifetime_points });
          }

      } catch (e) { console.error("Data Fetch Error:", e); } finally { setIsDataLoading(false); }
  };

  const dailyCheckIn = async () => {
    if (!currentUser) return;
    try {
        const { data, error } = await supabase.from('reward_ledger').insert({
            user_id: currentUser.id,
            amount: 10,
            transaction_type: 'checkin'
        });
        if (error) throw error;
        showToast("Daily check-in successful! +10 Coins", "success");
        fetchData();
    } catch (e) {
        showToast("Already checked in today!", "info");
    }
  };

  const logProductEvent = async (productId: string, eventType: 'view' | 'click' | 'add_to_cart') => {
      if (!currentUser) return;
      await supabase.from('product_events').insert({
          user_id: currentUser.id,
          product_id: productId,
          event_type: eventType
      });
  };

  const createGroupBuy = async (productId: string) => {
      if (!currentUser) return;
      const product = products.find(p => p.id === productId);
      if (!product) return;

      const { data, error } = await supabase.from('group_buys').insert({
          product_id: productId,
          creator_id: currentUser.id,
          group_price: product.price * 0.8, // 20% discount for group
          min_members: 2,
          expiry_time: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
      }).select().single();

      if (!error && data) {
          addToCart(product, 1, true, data.id);
          showToast("Group buy created! Invite friends to join.", "success");
          fetchData();
      }
  };

  const joinGroupBuy = async (productId: string, groupBuyId: string) => {
      const product = products.find(p => p.id === productId);
      if (!product) return;
      addToCart(product, 1, true, groupBuyId);
      showToast("Joined group buy! Checkout to confirm.", "success");
  };

  const initApp = async () => {
      try {
          await checkSession();
          await fetchData();
          setConnectionError(false);
      } catch (e) { console.error("Initialization Failed:", e);
      } finally { setIsLoading(false); setIsDataLoading(false); }
  };

  const checkSession = async () => {
      try {
          const { data, error } = await supabase.auth.getSession();
          if (data.session?.user) {
              const { data: profile } = await supabase.from('profiles').select('*').eq('id', data.session.user.id).maybeSingle();
              if (profile) setCurrentUser({ ...profile, roles: profile.roles || ['buyer'], avatarUrl: profile.avatar_url });
          }
      } catch (e) { console.error("Session check error:", e); } 
  };

  const addToCart = useCallback((p: Product, q = 1, isGroupBuy = false, groupBuyId?: string) => { 
      setCart(prev => { 
          const ex = prev.find(i => i.productId === p.id && i.isGroupBuy === isGroupBuy); 
          if (ex) return prev.map(i => (i.productId === p.id && i.isGroupBuy === isGroupBuy) ? { ...i, quantity: i.quantity + q } : i);
          return [...prev, { productId: p.id, quantity: q, product: p, isGroupBuy, groupBuyId }]; 
      }); 
      showToast(`Added ${p.title} to cart`, "success"); 
  }, [showToast]);

  const removeFromCart = useCallback((pid: string) => { setCart(prev => prev.filter(i => i.productId !== pid)); }, []);
  const updateCartQuantity = useCallback((pid: string, qty: number) => { if(qty <= 0) removeFromCart(pid); else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i)); }, [removeFromCart]);
  const clearCart = useCallback(() => { setCart([]); }, []);

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      try {
          for(const item of cart) {
              const subtotal = (item.isGroupBuy ? (item.product.activeGroupBuy?.groupPrice || item.product.price) : item.product.price) * item.quantity;
              const { data, error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: item.product.vendorId, 
                  items: [item], 
                  total: subtotal + fee, 
                  delivery_fee: fee, 
                  status: item.isGroupBuy ? 'pending_group' : 'placed', 
                  delivery_option: option,
                  group_buy_id: item.groupBuyId
              }).select().single();

              if (error) throw error;

              if (item.isGroupBuy && item.groupBuyId) {
                  await supabase.rpc('increment_group_member', { g_id: item.groupBuyId });
              }

              await supabase.from('products').update({ stock: Math.max(0, item.product.stock - item.quantity) }).eq('id', item.productId);
          }
          showToast("Order Successful!", "success"); clearCart(); fetchData();
      } catch (e) { showToast("Order failed", "error"); }
  };

  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) return { success: false, error: error.message };
      await checkSession(); fetchData();
      return { success: true, role: 'buyer' };
  };

  const logout = async () => { await supabase.auth.signOut(); setCurrentUser(null); setCurrentRole('guest'); setCart([]); };

  const contextValue = useMemo(() => ({
    currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, rewardWallet, flashSales, activeGroupBuys, unreadCount, isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed,
    login, signup: async () => ({ success: false }), logout, resetPassword: async () => ({ success: false }), updatePassword: async () => ({ success: false }), switchRole: () => {}, updateTheme: () => {}, toggleThemeSwitching: () => {},
    updateProfile: async () => ({ success: false }), submitContactMessage: async () => ({ success: false }), requestPayout: async () => ({ success: false }), uploadFile: async () => null, registerCourier: async () => ({ success: false }), registerVendor: async () => ({ success: false }), refreshData: fetchData,
    addProduct: async () => false, updateProduct: async () => {}, updateProductStatus: async () => {}, toggleTrendingStatus: async () => {}, deleteProduct: async () => {}, addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus: async () => {}, assignDelivery: async () => {}, toggleFavorite: () => {},
    markNotificationRead: async () => {}, markAllNotificationsRead: async () => {}, deleteNotification: async () => {}, sendNotification: async () => false, submitReview: async () => false, logProductEvent, dailyCheckIn, joinGroupBuy, createGroupBuy, banUser: async () => {}, deleteUser: async () => {}, approveVendor: async () => {}, approveCourier: async () => {}, toggleDriverStatus: async () => {}, updateDriverLocation: async () => {}, showToast, hideToast, requestNotificationPermission: async () => true
  }), [currentUser, products, vendors, orders, cart, notifications, rewardWallet, flashSales, activeGroupBuys, isDataLoading, toast, addToCart]);

  useEffect(() => { initApp(); }, []);

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) throw new Error('useApp must be used within an AppProvider');
  return context;
};

import React, { useEffect, useState, useRef } from 'react';
