// --- Countdown Timer (For Flash Sales) ---
export const CountdownTimer: React.FC<{ endTime: string }> = ({ endTime }) => {
    const [timeLeft, setTimeLeft] = useState<{h: number, m: number, s: number} | null>(null);

    useEffect(() => {
        const timer = setInterval(() => {
            const now = new Date().getTime();
            const distance = new Date(endTime).getTime() - now;

            if (distance < 0) {
                clearInterval(timer);
                setTimeLeft(null);
            } else {
                setTimeLeft({
                    h: Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)),
                    m: Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60)),
                    s: Math.floor((distance % (1000 * 60)) / 1000)
                });
            }
        }, 1000);
        return () => clearInterval(timer);
    }, [endTime]);

    if (!timeLeft) return <span className="text-red-500 font-bold uppercase text-[10px]">Ended</span>;

    const pad = (n: number) => n.toString().padStart(2, '0');

    return (
        <div className="flex gap-1 items-center font-mono text-[10px] font-black">
            <span className="bg-red-500 text-white px-1 rounded">{pad(timeLeft.h)}</span>
            <span className="text-red-500">:</span>
            <span className="bg-red-500 text-white px-1 rounded">{pad(timeLeft.m)}</span>
            <span className="text-red-500">:</span>
            <span className="bg-red-500 text-white px-1 rounded">{pad(timeLeft.s)}</span>
        </div>
    );
};

// --- Progress Bar (For Group Buys) ---
export const ProgressBar: React.FC<{ current: number, max: number, color?: string }> = ({ current, max, color = 'bg-primary' }) => {
    const percentage = Math.min(100, (current / max) * 100);
    return (
        <div className="w-full h-1.5 bg-gray-100 dark:bg-gray-800 rounded-full overflow-hidden">
            <div 
                className={`h-full ${color} transition-all duration-500 ease-out`}
                style={{ width: `${percentage}%` }}
            ></div>
        </div>
    );
};

// --- Avatar ---
interface AvatarProps {
  src?: string | null;
  name: string;
  size?: 'sm' | 'md' | 'lg' | 'xl' | '2xl';
  className?: string;
  onClick?: () => void;
}

export const Avatar: React.FC<AvatarProps> = ({ src, name, size = 'md', className = '', onClick }) => {
  const [imgError, setImgError] = useState(false);
  useEffect(() => { setImgError(false); }, [src]);
  const initials = name ? name.split(' ').slice(0, 2).map(n => n[0]).join('').toUpperCase() : '?';
  const sizeClasses = { sm: "w-8 h-8 text-[10px]", md: "w-10 h-10 text-xs", lg: "w-14 h-14 text-sm", xl: "w-24 h-24 text-xl", '2xl': "w-32 h-32 text-3xl" };
  const baseClasses = `rounded-full flex items-center justify-center font-bold object-cover shadow-sm border border-white dark:border-gray-800 flex-shrink-0 ${sizeClasses[size]} ${className}`;
  if (src && !imgError) return <img src={src} alt={name} className={`${baseClasses} bg-gray-100 dark:bg-gray-800`} onError={() => setImgError(true)} onClick={onClick} />;
  return <div className={`${baseClasses} bg-indigo-100 text-indigo-600`} onClick={onClick}>{initials}</div>;
};

// --- Button ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger' | 'success' | 'flash';
  fullWidth?: boolean;
  size?: 'sm' | 'md' | 'lg';
  icon?: string;
}

export const Button: React.FC<ButtonProps> = ({ children, variant = 'primary', fullWidth, size = 'md', icon, className = '', ...props }) => {
  const base = "inline-flex items-center justify-center rounded-2xl font-semibold transition-all duration-300 active:scale-[0.96] disabled:opacity-50 disabled:active:scale-100 tracking-tight";
  const variants = {
    primary: "bg-gradient-to-r from-primary to-primaryDark text-white hover:shadow-glow shadow-lg shadow-primary/30 border border-transparent",
    secondary: "bg-white dark:bg-darkSurface text-gray-800 dark:text-white border border-gray-100 dark:border-gray-800 hover:bg-gray-50 dark:hover:bg-gray-800 shadow-sm",
    outline: "border-2 border-primary/20 text-primary dark:text-primaryLight bg-transparent hover:bg-primary/5",
    ghost: "bg-transparent text-gray-500 dark:text-gray-400 hover:bg-gray-100/50 dark:hover:bg-gray-800/50 hover:text-gray-900 dark:hover:text-white shadow-none",
    danger: "bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 hover:bg-red-100 border border-red-100 dark:border-red-900/30",
    success: "bg-green-500 text-white hover:bg-green-600 shadow-lg shadow-green-500/30 border border-transparent",
    flash: "bg-gradient-to-r from-orange-500 to-red-600 text-white shadow-lg shadow-orange-500/30"
  };
  const sizes = { sm: "px-3 py-1.5 text-xs", md: "px-5 py-3 text-sm", lg: "px-8 py-4 text-base" };
  return <button className={`${base} ${variants[variant]} ${sizes[size]} ${fullWidth ? 'w-full' : ''} ${className}`} {...props}>{icon && <i className={`fa-solid fa-${icon} mr-2.5`}></i>}{children}</button>;
};

