export const Spinner: React.FC = () => <div className="animate-spin rounded-full h-6 w-6 border-2 border-gray-200 dark:border-gray-800 border-b-primary"></div>;

// --- Toast Notification ---
export const Toast: React.FC<{ toast: ToastMessage | null; onClose: () => void }> = ({ toast, onClose }) => {
    const [isVisible, setIsVisible] = useState(false);
    useEffect(() => {
        if (toast) {
            setIsVisible(true);
            const t = setTimeout(() => setIsVisible(false), 3000);
            return () => clearTimeout(t);
        }
    }, [toast?.id]);
    if (!toast) return null;
    const colors = { success: 'bg-green-600', error: 'bg-red-500', info: 'bg-blue-600' };
    return (
        <div className={`fixed top-6 left-1/2 transform -translate-x-1/2 z-[9999] transition-all duration-300 ${isVisible ? 'translate-y-0 opacity-100 scale-100' : '-translate-y-12 opacity-0 scale-90'}`}>
            <div className={`flex items-center gap-4 px-6 py-4 rounded-full shadow-2xl ${colors[toast.type]} text-white border border-white/20 backdrop-blur-md`}>
                <p className="text-xs font-bold">{toast.message}</p>
            </div>
        </div>
    );
};

