                             <div className="flex items-baseline gap-2">
                                <span className="text-4xl font-black text-gray-900 dark:text-white">₵{currentPrice.toFixed(2)}</span>
                                {flash && <span className="text-lg text-gray-400 line-through font-bold">₵{product.price}</span>}
                             </div>
                        </div>

                        {/* GROUP BUY SECTION */}
                        {product.activeGroupBuy ? (
                            <Card className="p-5 border-2 border-indigo-100 dark:border-primary/20 mb-8 bg-indigo-50/30 dark:bg-indigo-900/5">
                                <div className="flex justify-between items-center mb-3">
                                    <div>
                                        <p className="text-[9px] font-black text-primary uppercase tracking-[0.2em]">Team Price</p>
                                        <p className="text-2xl font-black text-indigo-600 dark:text-primaryLight">₵{product.activeGroupBuy.groupPrice.toFixed(2)}</p>
                                    </div>
                                    <Badge color="blue" className="h-fit">Group of {product.activeGroupBuy.minMembers}</Badge>
                                </div>
                                <div className="mb-4">
                                    <div className="flex justify-between text-[10px] font-bold text-gray-500 mb-1">
                                        <span>Progress</span>
                                        <span>{product.activeGroupBuy.currentMembers}/{product.activeGroupBuy.minMembers} Members</span>
                                    </div>
                                    <ProgressBar current={product.activeGroupBuy.currentMembers} max={product.activeGroupBuy.minMembers} />
