                                        <p className="text-sm font-bold text-gray-800 dark:text-white">Start a Team</p>
                                        <p className="text-[10px] text-gray-400 font-bold uppercase">Unlock ₵{(product.price * 0.8).toFixed(2)} Price</p>
                                    </div>
                                </div>
                                <i className="fa-solid fa-plus text-primary"></i>
                            </div>
                        )}

                        <div className="mb-8">
                            <h3 className="font-display font-black text-gray-900 dark:text-white text-sm uppercase tracking-widest mb-3 opacity-60">Description</h3>
                            <p className="text-gray-600 dark:text-gray-400 leading-relaxed text-sm">{product.description}</p>
                        </div>

                        <div className="mt-auto space-y-4">
                            <div className="flex gap-4">
                                <div className="flex items-center bg-gray-100 dark:bg-gray-800 rounded-2xl h-14 w-32 px-2">
                                    <button onClick={() => setQuantity(Math.max(1, quantity-1))} className="w-10 h-10 text-gray-500 hover:text-primary"><i className="fa-solid fa-minus"></i></button>
                                    <span className="flex-1 text-center font-black text-lg dark:text-white">{quantity}</span>
                                    <button onClick={() => setQuantity(Math.min(product.stock, quantity+1))} className="w-10 h-10 text-gray-500 hover:text-primary"><i className="fa-solid fa-plus"></i></button>
                                </div>
                                <Button 
                                    fullWidth 
                                    size="lg" 
                                    className="h-14 shadow-xl" 
                                    onClick={() => addToCart(product, quantity)}
                                    icon="cart-plus"
                                >
                                    Standard Buy
                                </Button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

// --- Review Modal ---
export const ReviewModal: React.FC<{ productId: string, vendorId: string, existingReview?: Review, onClose: () => void }> = ({ productId, vendorId, existingReview, onClose }) => {
    const { submitReview, currentUser } = useApp();
    const [rating, setRating] = useState(existingReview?.rating || 5);
    const [comment, setComment] = useState(existingReview?.comment || '');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async () => {
        if (!currentUser) return;
        setLoading(true);
        await submitReview({
            id: existingReview?.id || '',
            productId,
            vendorId,
            userId: currentUser.id,
            rating,
            comment,
            images: []
        });
        setLoading(false);
        onClose();
    };

    return (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
            <Card className="w-full max-w-md p-6 animate-slide-up">
                <h3 className="text-xl font-bold mb-4 dark:text-white">{existingReview ? 'Edit Review' : 'Rate Product'}</h3>
                <div className="flex gap-2 mb-4">
                    {[1, 2, 3, 4, 5].map(star => (
                        <button key={star} onClick={() => setRating(star)} className={`text-2xl transition-colors ${star <= rating ? 'text-yellow-400' : 'text-gray-300'}`}>
                            <i className="fa-solid fa-star"></i>
                        </button>
                    ))}
                </div>
                <textarea 
                    className="w-full p-3 rounded-xl bg-gray-50 dark:bg-darkBg border border-gray-100 dark:border-gray-800 text-sm mb-4 outline-none focus:ring-2 focus:ring-primary/20 dark:text-white"
                    placeholder="Write your review..."
                    value={comment}
                    onChange={(e) => setComment(e.target.value)}
                    rows={4}
                />
                <div className="flex gap-3">
                    <Button fullWidth onClick={handleSubmit} disabled={loading}>{loading ? 'Saving...' : 'Submit'}</Button>
                    <Button variant="secondary" fullWidth onClick={onClose}>Cancel</Button>
                </div>
            </Card>
        </div>
    );
};

