                            <Button fullWidth size="lg" onClick={() => navigate('/buyer/checkout')} className="h-14">Checkout Now</Button>
                            <button onClick={clearCart} className="w-full text-xs font-bold text-gray-400 hover:text-red-500 transition-colors uppercase tracking-widest">Clear Cart</button>
                        </Card>
                    </>
                )}
            </div>
        </div>
