// --- Checkout Page ---
export const Checkout: React.FC = () => {
    const { cart, placeOrder } = useApp();
    const navigate = useNavigate();
    const [deliveryOption, setDeliveryOption] = useState<'delivery' | 'pickup'>('delivery');
    const [isPlacing, setIsPlacing] = useState(false);

    const subtotal = cart.reduce((acc, item) => {
        const price = item.isGroupBuy ? (item.product.activeGroupBuy?.groupPrice || item.product.price) : item.product.price;
        return acc + price * item.quantity;
    }, 0);
    const deliveryFee = deliveryOption === 'delivery' ? 5 : 0;
    const total = subtotal + deliveryFee;

    const handlePlaceOrder = async () => {
        setIsPlacing(true);
        try {
            await placeOrder(deliveryOption, deliveryFee);
            navigate('/buyer/orders');
        } catch (e) {
            console.error(e);
        } finally {
            setIsPlacing(false);
        }
    };

    if (cart.length === 0) return <Navigate to="/buyer/dashboard" />;

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-24 animate-fade-in">
            <div className="bg-white dark:bg-darkSurface p-4 shadow-sm sticky top-0 z-30 flex items-center gap-3 border-b border-gray-100 dark:border-gray-800">
                <button onClick={() => navigate(-1)} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 dark:text-white transition-colors"><i className="fa-solid fa-arrow-left"></i></button>
                <h1 className="text-xl font-bold font-display dark:text-white">Checkout</h1>
            </div>
            <div className="p-4 space-y-6 max-w-md mx-auto">
                <Card className="p-6">
                    <h3 className="font-bold mb-4 dark:text-white uppercase text-xs tracking-widest text-gray-400">Select Method</h3>
                    <div className="grid grid-cols-2 gap-4">
                        <div 
                            onClick={() => setDeliveryOption('delivery')}
                            className={`p-6 border-2 rounded-3xl cursor-pointer text-center transition-all ${deliveryOption === 'delivery' ? 'border-primary bg-primary/5 text-primary shadow-glow shadow-primary/10' : 'border-gray-100 dark:border-gray-800 text-gray-400'}`}
                        >
                            <i className="fa-solid fa-motorcycle text-xl mb-2"></i>
                            <p className="text-xs font-black uppercase tracking-widest">Delivery</p>
                            <p className="text-[10px] mt-1">₵5.00</p>
                        </div>
                        <div 
                            onClick={() => setDeliveryOption('pickup')}
                            className={`p-6 border-2 rounded-3xl cursor-pointer text-center transition-all ${deliveryOption === 'pickup' ? 'border-primary bg-primary/5 text-primary shadow-glow shadow-primary/10' : 'border-gray-100 dark:border-gray-800 text-gray-400'}`}
                        >
                            <i className="fa-solid fa-person-walking text-xl mb-2"></i>
                            <p className="text-xs font-black uppercase tracking-widest">Pickup</p>
                            <p className="text-[10px] mt-1">Free</p>
                        </div>
                    </div>
                </Card>

                <Card className="p-6">
                    <h3 className="font-bold mb-4 dark:text-white uppercase text-xs tracking-widest text-gray-400">Summary</h3>
                    <div className="space-y-3">
                        <div className="flex justify-between text-sm">
                            <span className="text-gray-500">Items Subtotal</span>
                            <span className="font-bold dark:text-white">₵{subtotal.toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-sm">
                            <span className="text-gray-500">Delivery Service</span>
                            <span className="font-bold dark:text-white">₵{deliveryFee.toFixed(2)}</span>
                        </div>
                        <div className="h-px bg-gray-100 dark:bg-gray-800 my-2"></div>
                        <div className="flex justify-between items-end">
                            <span className="text-xs font-black uppercase text-gray-400">Amount Due</span>
                            <span className="text-2xl font-black dark:text-white text-primary">₵{total.toFixed(2)}</span>
                        </div>
                    </div>
                </Card>

                <Button fullWidth size="lg" onClick={handlePlaceOrder} disabled={isPlacing} className="h-16 shadow-xl shadow-primary/30 mt-2">
                    {isPlacing ? 'Processing...' : `Confirm Order (₵${total.toFixed(2)})`}
                </Button>
            </div>
        </div>
    );
};

